      const s = clamp(q / duty, 0, 1);
      const smooth = s * s * (3 - 2 * s);
      const smoothRate = 6 * s * (1 - s) * freq / duty;
      const sn = Math.sin(Math.PI * s);
      const shape2 = sn * sn;

      hipPos = front - (front + effectiveRear) * smooth;
      hipVel = -(front + effectiveRear) * smoothRate;
      kneeTarget = -kneeBase + 0.04 * shape2;
      kneeTargetSpeed =
        0.04 * Math.PI * Math.sin(2 * Math.PI * s) * freq / duty;
    } else {
      const swingDuration = Math.max(0.08, 1 - duty);
      const s = clamp((q - duty) / swingDuration, 0, 1);
      swingS = s;
      const smooth = s * s * (3 - 2 * s);
      const smoothRate = 6 * s * (1 - s) * freq / swingDuration;
      const sn = Math.sin(Math.PI * s);
      const sin2 = Math.sin(2 * Math.PI * s);
      const shape2 = sn * sn;

      hipPos = -effectiveRear + (front + effectiveRear) * smooth;
      hipVel = (front + effectiveRear) * smoothRate;
      kneeTarget = -kneeBase - swingFlex * shape2;
      kneeTargetSpeed =
        -swingFlex * Math.PI * sin2 * freq / swingDuration;

      const lift = clamp(obstacleGain * rise, 0, 0.56);
      kneeTarget -= lift * (0.20 + 0.80 * shape2);
      kneeTargetSpeed -=
        lift * 0.80 * Math.PI * sin2 * freq / swingDuration;
      hipPos += 0.28 * lift * shape2;
      hipVel += 0.28 * lift * Math.PI * sin2 * freq / swingDuration;

      const reach = Math.min(0.40, obstacleGain * drop * 0.45);
      kneeTarget += reach * shape2;
      kneeTargetSpeed +=
        reach * Math.PI * sin2 * freq / swingDuration;

