      hipKp * (hipTarget - hipAngle) +
      hipKd * (hipTargetSpeed - hipSpeed);
    let kneeTorque =
      kneeKp * (kneeTarget - kneeAngle) +
      kneeKd * (kneeTargetSpeed - kneeSpeed);

