      clamp(hipTorque / 210, -1, 1),
      clamp(kneeTorque / 172, -1, 1)
    ];
  }

  const outA = leg(
    phaseA, 5, 6, 7, 8, footA, weightA / weightSum
  );
  const outB = leg(
    phaseB, 10, 11, 12, 13, footB, weightB / weightSum
  );
  return [outA[0], outA[1], outB[0], outB[1]];
}

