    110
  );

  function leg(q, hipIndex, hipSpeedIndex, kneeIndex, kneeSpeedIndex, foot, share) {
    q = wrap01(q);
    const inStance = q < duty;
    let hipPos, hipVel, kneeTarget, kneeTargetSpeed;
    let swingS = 0;

    if (inStance) {
      const s = clamp(q / duty, 0, 1);
      const smooth = s * s * (3 - 2 * s);
      const smoothRate = 6 * s * (1 - s) * freq / duty;
      const shape = Math.sin(Math.PI * s) ** 2;

      hipPos = front - (front + effectiveRear) * smooth;
      hipVel = -(front + effectiveRear) * smoothRate;
      kneeTarget = -kneeBase + 0.035 * shape;
      kneeTargetSpeed =
        0.035 * Math.PI * Math.sin(2 * Math.PI * s) * freq / duty;
    } else {
      const swingDuration = Math.max(0.08, 1 - duty);
      const s = clamp((q - duty) / swingDuration, 0, 1);
      swingS = s;
      const smooth = s * s * (3 - 2 * s);
      const smoothRate = 6 * s * (1 - s) * freq / swingDuration;
      const shape = Math.sin(Math.PI * s) ** 2;
      const sin2 = Math.sin(2 * Math.PI * s);

      hipPos = -effectiveRear + (front + effectiveRear) * smooth;
      hipVel = (front + effectiveRear) * smoothRate;
      kneeTarget = -kneeBase - swingFlex * shape;
      kneeTargetSpeed =
        -swingFlex * Math.PI * sin2 * freq / swingDuration;

      const lift = clamp(terrainGain * rise, 0, 0.62);
      kneeTarget -= lift * (0.18 + 0.82 * shape);
      kneeTargetSpeed -=
        lift * 0.82 * Math.PI * sin2 * freq / swingDuration;
      hipPos += 0.20 * lift * shape;
      hipVel +=
        0.20 * lift * Math.PI * sin2 * freq / swingDuration;

      const reach = clamp(terrainGain * drop * 0.35, 0, 0.30);
      kneeTarget += reach * shape;
      kneeTargetSpeed +=
        reach * Math.PI * sin2 * freq / swingDuration;
    }

    kneeTarget += heightCorrection * (inStance ? 1 : 0.45);
    kneeTarget -= landingBend * (inStance ? 1 : 0.65);

    if (inStance && !foot) kneeTarget += 0.08;
    if (!inStance && foot) {
      const bend = toeOff * (1 - 0.45 * swingS);
      kneeTarget = Math.min(kneeTarget, -kneeBase - bend);
      if (swingS < 0.20) {
        kneeTargetSpeed = Math.min(kneeTargetSpeed, -0.35 * toeOff);
      }
    }

    let hipTarget = hipPos + pitchCorrection + hipBias;
    let hipTargetSpeed = hipVel + balanceGain * torsoSpin;

    hipTarget = clamp(hipTarget, -0.88, 1.18);
    kneeTarget = clamp(kneeTarget, -1.62, -0.06);
    hipTargetSpeed = clamp(hipTargetSpeed, -6.8, 6.8);
    kneeTargetSpeed = clamp(kneeTargetSpeed, -6.4, 6.4);

    const hipAngle = read(hipIndex, 0);
    const hipSpeed = read(hipSpeedIndex, 0);
    const kneeAngle = read(kneeIndex, -0.2);
    const kneeSpeed = read(kneeSpeedIndex, 0);

    let hipTorque =
      hipKp * (hipTarget - hipAngle) +
      hipKd * (hipTargetSpeed - hipSpeed) +
      bodyTorque * share;
    let kneeTorque =
      kneeKp * (kneeTarget - kneeAngle) +
      kneeKd * (kneeTargetSpeed - kneeSpeed);

    if (hipAngle <= -0.885 && hipTorque < 0) hipTorque *= 0.12;
    if (hipAngle >= 1.185 && hipTorque > 0) hipTorque *= 0.12;
    if (kneeAngle <= -1.685 && kneeTorque < 0) kneeTorque *= 0.12;
    if (kneeAngle >= -0.065 && kneeTorque > 0) kneeTorque *= 0.12;

    if (hipSpeed > 7.05 && hipTorque > 0) hipTorque *= 0.2;
    if (hipSpeed < -7.05 && hipTorque < 0) hipTorque *= 0.2;
    if (kneeSpeed > 6.65 && kneeTorque > 0) kneeTorque *= 0.2;
    if (kneeSpeed < -6.65 && kneeTorque < 0) kneeTorque *= 0.2;

    return [
      clamp(hipTorque / 210, -1, 1),
      clamp(kneeTorque / 172, -1, 1)
    ];
  }

  const outA = leg(phaseA, 5, 6, 7, 8, footA, weightA / weightSum);
  const outB = leg(phaseB, 10, 11, 12, 13, footB, weightB / weightSum);
  return [outA[0], outA[1], outB[0], outB[1]];
}

function learn(lab) {
  const bounds = [
    [0.68, 1.8],    // frequency
    [0.25, 1.04],   // forward hip angle
    [0.08, 0.68],   // rear hip angle magnitude
    [0.45, 0.70],   // stance fraction
    [0.02, 0.32],   // stance knee bend
    [0.25, 1.35],   // swing knee flex
    [80, 360],      // hip position gain
    [3, 38],        // hip velocity gain
    [45, 260],      // knee position gain
    [6, 50],        // knee velocity gain
    [0.55, 1.95],   // torso feedback
    [0, 1],         // initial phase
    [0.15, 1.2],    // height recovery
    [0.8, 2.5],     // terrain response
    [-0.30, 0.18],  // hip bias
    [0, 0.5],       // inter-leg phase
    [0.25, 1.6],    // desired forward speed
    [0, 0.3],       // stride response to speed
    [0, 105],       // direct torso-angle torque
    [0, 32],        // direct torso-spin torque
    [0, 0.36],      // toe-off bend
    [0.92, 1.12]    // torso height target
  ];
  const D = bounds.length;
  const wrap01 = x => x - Math.floor(x);
  const clamp01 = x => Math.max(0, Math.min(1, x));

  function reflect01(x) {
    if (!Number.isFinite(x)) return 0.5;
    x = ((x % 2) + 2) % 2;
