      1.35, 0.35, 0.65, 1.55, -0.08, 0.50, 0.90, 0.14,
      55, 12, 0.19, 1.02
    ],
    [
      0.82, 0.68, 0.26, 0.62, 0.08, 0.78, 170, 23, 90, 24,
      1.45, 0.40, 0.80, 1.50, 0, 0.50, 0.68, 0.10,
      75, 20, 0.18, 1.05
    ],
    [
      1.38, 0.87, 0.36, 0.52, 0.07, 1.02, 235, 12, 125, 26,
      1.25, 0.10, 0.35, 1.75, -0.10, 0.50, 1.05, 0.18,
      48, 9, 0.18, 1.03
    ],
    [
      1.10, 0.80, 0.34, 0.53, 0.08, 0.95, 205, 16, 115, 25,
      1.30, 0.10, 0.55, 1.55, -0.04, 0, 0.90, 0.15,
      60, 14, 0.19, 1.02
    ],
    [
      1.12, 0.84, 0.32, 0.56, 0.10, 0.92, 215, 17, 115, 29,
      1.40, 0.24, 0.65, 1.70, -0.08, 0.25, 0.90, 0.15,
      65, 14, 0.20, 1.03
    ],
    [
      0.95, 0.72, 0.25, 0.62, 0.10, 0.82, 185, 24, 100, 24,
      1.55, 0.60, 0.72, 1.45, 0.02, 0.50, 0.72, 0.10,
      85, 18, 0.20, 1.04
    ],
    [
      1.55, 0.96, 0.45, 0.50, 0.06, 1.15, 260, 13, 135, 24,
      1.10, 0.15, 0.42, 1.80, -0.12, 0.50, 1.20, 0.21,
      55, 9, 0.15, 1.00
    ],
    [
      0.90, 0.78, 0.32, 0.58, 0.11, 0.90, 220, 20, 115, 32,
      1.75, 0.50, 0.72, 1.65, -0.05, 0.50, 0.80, 0.12,
