      u = new Array(D);
      for (let d = 0; d < D; ++d) u[d] = Math.random();
    } else {
      const base = seedU[Math.floor(Math.random() * seedU.length)];
      const spread = 0.08 + 0.16 * Math.random();
      u = new Array(D);
      for (let d = 0; d < D; ++d) {
        u[d] = adjust01(base[d] + spread * randn(), d);
      }
    }

    pop.push({ u: u.slice(), score: evaluate(u) });
  }

  while (
    pop.length >= 4 &&
    remaining() >= reserve + pop.length
  ) {
    const old = pop.map(item => ({
      u: item.u.slice(),
      score: item.score
    }));

    let bestIndex = 0;
    for (let i = 1; i < old.length; ++i) {
      if (old[i].score > old[bestIndex].score) bestIndex = i;
    }

    const order = new Array(old.length);
    for (let i = 0; i < order.length; ++i) order[i] = i;
    for (let i = order.length - 1; i > 0; --i) {
      const j = Math.floor(Math.random() * (i + 1));
      const tmp = order[i];
      order[i] = order[j];
      order[j] = tmp;
    }

    for (let oi = 0; oi < order.length && remaining() > reserve; ++oi) {
      const target = order[oi];
      let r1, r2, r3;

      do { r1 = Math.floor(Math.random() * old.length); }
      while (r1 === target);
      do { r2 = Math.floor(Math.random() * old.length); }
      while (r2 === target || r2 === r1);
      do { r3 = Math.floor(Math.random() * old.length); }
      while (r3 === target || r3 === r1 || r3 === r2);

      const F = 0.38 + 0.42 * Math.random();
      const CR = 0.76 + 0.20 * Math.random();
      const strategy = Math.random();
      const forced = Math.floor(Math.random() * D);
      const candidate = old[target].u.slice();

      for (let d = 0; d < D; ++d) {
        if (d !== forced && Math.random() >= CR) continue;

        let donor;
        if (strategy < 0.28) {
          let diff = old[r1].u[d] - old[r2].u[d];
          if (d === 11) {
            if (diff > 0.5) diff -= 1;
            if (diff < -0.5) diff += 1;
          }
          donor = old[bestIndex].u[d] + F * diff;
        } else if (strategy < 0.62) {
