          let diff = old[r1].u[d] - old[r2].u[d];
          if (d === 11) {
            if (toBest > 0.5) toBest -= 1;
            if (toBest < -0.5) toBest += 1;
            if (diff > 0.5) diff -= 1;
            if (diff < -0.5) diff += 1;
