          donor = old[target].u[d] + F * toBest + F * diff;
        } else {
          let diff = old[r2].u[d] - old[r3].u[d];
          if (d === 11) {
            if (diff > 0.5) diff -= 1;
            if (diff < -0.5) diff += 1;
          }
          donor = old[r1].u[d] + F * diff;
        }

        candidate[d] = adjust01(donor, d);
      }

      const score = evaluate(candidate);
      if (score > pop[target].score) {
        pop[target] = { u: candidate.slice(), score: score };
      }
    }
  }

  if (!bestU) {
    bestU = seedU[0].slice();
    bestParams = decode(bestU);
  }

  for (let round = 0; round < 2 && remaining() > 0; ++round) {
    const step = round === 0 ? 0.040 : 0.018;
    for (let d = 0; d < D && remaining() > 0; ++d) {
      for (const sign of [-1, 1]) {
        if (remaining() <= 0) break;
        const candidate = bestU.slice();
        candidate[d] = adjust01(candidate[d] + sign * step, d);
        evaluate(candidate);
      }
    }
  }

  let sigma = 0.055;
  let stalled = 0;
  while (remaining() > 0) {
    const candidate = bestU.slice();
    const changes = 1 + Math.floor(Math.random() * 4);

    for (let k = 0; k < changes; ++k) {
      const d = Math.floor(Math.random() * D);
      candidate[d] = adjust01(candidate[d] + sigma * randn(), d);
    }

    const previousBest = bestScore;
    evaluate(candidate);

    if (bestScore > previousBest) {
      stalled = 0;
      sigma = Math.min(0.12, sigma * 1.07);
    } else {
      ++stalled;
