    return (typeof v === "number" && isFinite(v)) ? v : d;
  }
  function av(i, d) {
    return num(a[i], d);
  }
  function ex(i, d) {
    const idx = N + 6 + i;
    return (a.length > idx && typeof a[idx] === "number" && isFinite(a[idx])) ? a[idx] : d;
  }

  const sHA = (a.length > N + 0 && a[N + 0] < 0) ? -1 : 1;
  const sHB = (a.length > N + 1 && a[N + 1] < 0) ? -1 : 1;
  const sKA = (a.length > N + 2 && a[N + 2] < 0) ? -1 : 1;
  const sKB = (a.length > N + 3 && a[N + 3] < 0) ? -1 : 1;
  const hMap = (a.length > N + 4 && a[N + 4] < 0) ? -1 : 1;
  const kMap = (a.length > N + 5 && a[N + 5] < 0) ? -1 : 1;

  const obsLiftGain = clampF(ex(0, 0), 0, 2.5);
  const obsSlow = clampF(ex(1, 0), 0, 0.8);
  const obsFreq = clampF(ex(2, 0), 0, 1.5);
  const obsBody = clampF(ex(3, 0), 0, 0.25);
  const obsBal = clampF(ex(4, 0), -120, 120);

  const t = num(o[19], 0);
  const phi = num(o[0], 0);
  const spin = num(o[1], 0);
  const vx = num(o[2], 0);
  const vy = num(o[3], 0);
  const height = num(o[4], 1.1);

  const hips = [num(o[5], 0), num(o[10], 0)];
  const hipSpds = [num(o[6], 0), num(o[11], 0)];
  const knees = [num(o[7], 0), num(o[12], 0)];
  const kneeSpds = [num(o[8], 0), num(o[13], 0)];
  const feet = [num(o[9], 0) > 0.5 ? 1 : 0, num(o[14], 0) > 0.5 ? 1 : 0];

  const h1 = num(o[15], 0);
  const h2 = num(o[16], 0);
  const h3 = num(o[17], 0);
  const h4 = num(o[18], 0);

  let hMax = Math.max(0, h1, 0.8 * h2, 0.6 * h3, 0.4 * h4);
  const prep = clampF((hMax - 0.02) / 0.23, 0, 1);
  let terr = Math.max(0, h1, 0.8 * h2, 0.6 * h3, 0.4 * h4);
  terr = clampF(terr, 0, 0.45);

  let M = mem;
  if (!M || typeof M !== "object") M = {};

  if (!M.init || (typeof M.lastT === "number" && t < M.lastT - 0.05)) {
    M.init = 1;
    M.lastT = t;
    M.q = [0, wrap1(av(2, 0.5))];
    M.initH = [hips[0], hips[1]];
    M.initK = [knees[0], knees[1]];
    M.slow = 0;
    M.x = 0;
    M.lastKick = -10;
    M.kickUntil = -1;
  }

  let dt = 1 / 60;
  if (typeof M.lastT === "number") {
    const dd = t - M.lastT;
    if (dd > 0 && dd < 0.2) dt = dd;
  }
  M.lastT = t;

  const freq = clampF(av(0, 1.8), 0.5, 4.0);
  const duty = clampF(av(1, 0.58), 0.25, 0.85);
  const phaseOff = wrap1(av(2, 0.5));
  const stride = clampF(av(3, 0.30), 0.0, 0.7);
  const baseY = clampF(av(4, 0.78), 0.45, 0.82);
  const lift = clampF(av(5, 0.15), 0.0, 0.5);
  const kneeBias = clampF(av(6, 0.0), -0.6, 0.6);
  const hipBias = clampF(av(7, 0.0), -0.5, 0.5);
  const cTorso = clampF(av(8, 1.0), -2.5, 2.5);
  const phiDes = clampF(av(9, -0.05), -0.9, 0.5);
  const vDes = clampF(av(10, 1.0), -1.0, 3.0);
  const heightTarget = clampF(av(11, 1.10), 0.60, 1.50);
  const Kh = clampF(av(12, 1.0), -2.0, 3.0);

  const KxPhi = clampF(av(13, -0.6), -5.0, 5.0);
  const KxSpin = clampF(av(14, -0.15), -3.0, 3.0);
  const KxV = clampF(av(15, 0.25), -4.0, 4.0);
  const KbPhi = clampF(av(16, -80), -400, 400);
  const KbSpin = clampF(av(17, -15), -200, 200);
  const KbV = clampF(av(18, 8), -300, 300);
  const wSwing = clampF(av(19, 0.5), 0.0, 2.0);

  const kpH = clampF(av(20, 220), 0, 800);
  const kdH = clampF(av(21, 12), 0, 150);
  const kpK = clampF(av(22, 220), 0, 800);
  const kdK = clampF(av(23, 12), 0, 150);
  const kneeStance = clampF(av(24, 0.0), -1.0, 1.0);
  const contactAdj = Math.max(0, clampF(av(25, 0.02), 0, 0.2));
  const terrainLiftGain = Math.max(0, clampF(av(26, 0.5), 0, 2.0));
  const terrainHip = clampF(av(27, 0.2), -2.0, 2.0);
  const ffHip = clampF(av(28, 0.0), -1.5, 1.5);
  const ffKnee = clampF(av(29, 0.0), -1.5, 1.5);
  const rampT = clampF(av(30, 0.35), 0.02, 1.5);
  const stanceBounce = clampF(av(31, 0.0), -0.4, 0.4);
  const kneeSwingExtra = clampF(av(32, 0.0), -1.0, 1.0);

  const rr = clamp01(t / rampT);
  const ramp = rr * rr * (3 - 2 * rr);

  M.x += vx * dt;
  if (t > 0.9 && t < 19.5) {
    if (Math.abs(vx) < 0.05 && height < 1.0) {
      M.slow += dt;
    } else {
      M.slow = Math.max(0, M.slow - dt * 2.5);
    }
  } else {
    M.slow = 0;
  }

  if (M.slow > 0.9 && t > M.lastKick + 1.2 && t < 18.5) {
    M.kickUntil = t + 0.9;
    M.lastKick = t;
    M.slow = 0;
    M.q[0] = 0;
    M.q[1] = phaseOff;
  }

  const kick = t < M.kickUntil ? 1 : 0;
  const rate = freq * (1 + 0.5 * kick) * (1 + obsFreq * prep);
  const phaseScale = ramp < 1 ? (0.25 + 0.75 * ramp) : 1;

  M.q[0] = wrap1(M.q[0] + rate * dt * phaseScale);
  M.q[1] = wrap1(M.q[1] + rate * dt * phaseScale);

  let em = 0;
  if (t > 0.6) {
    if (height < 0.62) em = Math.max(em, (0.62 - height) / 0.25);
    if (Math.abs(phi) > 0.85 && height < 0.95) {
      em = Math.max(em, (Math.abs(phi) - 0.85) / 0.5);
    }
  }
  em = clampF(em, 0, 1);

  let yBase = baseY + Kh * (heightTarget - height);
  if (em > 0) yBase = Math.max(yBase, 0.74 + 0.06 * em);

  const ePhi = phi - phiDes;
  const vErr = vx - vDes;
  const xBal = KxPhi * ePhi + KxSpin * spin + KxV * vErr;
  let balT = KbPhi * ePhi + KbSpin * spin + KbV * vErr;
  balT += obsBal * prep;
  if (em > 0) balT *= (1 + 0.5 * em);

  const out = [0, 0, 0, 0];

  for (let i = 0; i < 2; i++) {
    let q = wrap1(M.q[i]);
    let isStance = q < duty;

    if (t > rampT + 0.12) {
      const denS = 1 - duty;
      if (!isStance && feet[i] > 0.5 && denS > 1e-4) {
        const us = (q - duty) / denS;
        if (us > 0.75 && us < 1.001) {
          q = 0;
          isStance = true;
        }
      } else if (isStance && feet[i] < 0.5 && q > 0.95 * duty) {
        q = duty + 1e-5;
        isStance = false;
      }
    }
    M.q[i] = wrap1(q);

    let u = 0;
    let xVal = 0;
    let liftAmt = 0;
    const strideUse = stride * (1 + 0.35 * kick) * (1 - obsSlow * prep);

    if (isStance) {
      u = clampF(q / duty, 0, 1);
      xVal = strideUse * (1 - 2 * u);
    } else {
      const den = 1 - duty;
      u = clampF((q - duty) / Math.max(den, 1e-4), 0, 1);
      const sm = u * u * (3 - 2 * u);
      xVal = strideUse * (-1 + 2 * sm);
      liftAmt = Math.sin(Math.PI * u);
      if (liftAmt < 0) liftAmt = 0;
    }

    const extraLift = obsLiftGain * Math.min(0.4, Math.max(0, hMax - 0.02));
    const totalLift = (lift * (1 + 0.6 * kick) + terrainLiftGain * terr + extraLift) * liftAmt;

    let xDes = xVal + xBal + terrainHip * terr * liftAmt;
    if (em > 0) xDes *= (1 - 0.4 * em);

    let yDes = yBase;
    if (isStance) {
      yDes += stanceBounce * Math.sin(Math.PI * u);
      if (feet[i] < 0.5) yDes += contactAdj * (1 + 0.5 * (1 - u));
      yDes += obsBody * prep;
    } else {
      yDes -= totalLift;
      if (feet[i] > 0.5) yDes -= contactAdj * 0.5;
    }
    if (em > 0) yDes += 0.10 * em;
    yDes = clampF(yDes, 0.15, 0.818);

    const sol = solveIK(xDes, yDes);
    let targetH = hMap * sol[0] - cTorso * phi + hipBias;
    let targetK = kMap * sol[1] + kneeBias;

    if (isStance) {
      targetK += kneeStance * (1 - u);
    } else {
      targetK -= kneeSwingExtra * liftAmt;
    }
    if (em > 0) targetK += 0.12 * em;

    targetH = clampF(targetH, -0.89, 1.19);
    targetK = clampF(targetK, -1.68, -0.055);

    if (ramp < 1) {
      const ih = (M.initH && typeof M.initH[i] === "number") ? M.initH[i] : targetH;
      const ik = (M.initK && typeof M.initK[i] === "number") ? M.initK[i] : targetK;
      targetH = ih + (targetH - ih) * ramp;
      targetK = ik + (targetK - ik) * ramp;
    }

    const weight = isStance ? 1.0 : wSwing;
    let hipU = kpH * (targetH - hips[i]) - kdH * hipSpds[i] + balT * weight + ffHip * 210;
    let kneeU = kpK * (targetK - knees[i]) - kdK * kneeSpds[i] + ffKnee * 172 + 35 * em;

    if (!isFinite(hipU)) hipU = 0;
    if (!isFinite(kneeU)) kneeU = 0;

    const sH = i === 0 ? sHA : sHB;
    const sK = i === 0 ? sKA : sKB;

    let ho = sH * hipU / 210;
    let ko = sK * kneeU / 172;

    if (!isFinite(ho)) ho = 0;
    if (!isFinite(ko)) ko = 0;
    if (ho > 1) ho = 1;
    else if (ho < -1) ho = -1;
    if (ko > 1) ko = 1;
    else if (ko < -1) ko = -1;

    out[2 * i] = ho;
    out[2 * i + 1] = ko;
  }

  if (TRACE && TRACE.on) {
    const T = TRACE;
    T.n++;
    const ap = Math.abs(phi);
    const asp = Math.abs(spin);
    T.sumPhi2 += phi * phi;
    T.sumSpin2 += spin * spin;
    T.sumAbsPhi += ap;
    T.sumHeight += height;
    T.sumVx += vx;
    if (height < T.minH) T.minH = height;
    if (height > T.maxH) T.maxH = height;
    if (ap > T.maxAbsPhi) T.maxAbsPhi = ap;
    if (asp > T.maxAbsSpin) T.maxAbsSpin = asp;
    if (height < 0.58) T.lowTime += dt;
    if (ap > 1.0) T.badAngleTime += dt;
    if (t > 8) {
      T.tailN++;
      T.tailPhi += phi;
      T.tailVx += vx;
      T.tailHeight += height;
      T.tailAbsPhi += ap;
    }
    T.finalT = t;
    T.finalPhi = phi;
    T.finalSpin = spin;
    T.finalVx = vx;
    T.finalVy = vy;
    T.finalHeight = height;
    T.feet = [feet[0], feet[1]];
    T.q = [M.q[0], M.q[1]];
  }

  return out;
}

function learn(lab) {
  const tStart = (typeof Date !== "undefined" && Date.now) ? Date.now() : 0;
  let used = 0;

  const DIM = N + E;
  const cache = Object.create(null);
  const allRecs = [];
  let bestScoreGlobal = -1e100;
  let bestRecGlobal = null;

  function timeOK() {
    if (!tStart) return true;
    return (Date.now() - tStart) < 168000;
  }

  function trialsLeft() {
    try {
      if (lab && typeof lab.trialsLeft === "function") {
        const n = lab.trialsLeft();
        if (typeof n === "number" && isFinite(n)) return n;
      }
    } catch (e) {}
    return 1000 - used;
  }

  function gauss() {
    let u = Math.random();
    if (u < 1e-12) u = 1e-12;
    let v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  function xKey(x) {
    let s = "";
    for (let i = 0; i < x.length; i++) {
      let v = x[i];
      if (typeof v !== "number" || !isFinite(v)) v = 0;
      s += (Math.round(v * 1000000) / 1000000) + ",";
    }
    return s;
  }

  function zFromX(x) {
    const z = new Array(DIM);
    for (let i = 0; i < N; i++) {
      let v = (x && typeof x[i] === "number" && isFinite(x[i])) ? x[i] : DEF[i];
      z[i] = clamp01((v - MIN[i]) / (MAX[i] - MIN[i]));
    }
    for (let e = 0; e < E; e++) {
      const idx = N + 6 + e;
      let v = (x && typeof x[idx] === "number" && isFinite(x[idx])) ? x[idx] : EMIN[e];
      z[N + e] = clamp01((v - EMIN[e]) / (EMAX[e] - EMIN[e]));
    }
    return z;
  }

  function decode(z, signs) {
    const x = new Array(LEN);
    for (let i = 0; i < N; i++) {
      let zz = (z && typeof z[i] === "number" && isFinite(z[i])) ? clamp01(z[i]) : 0;
      let v = MIN[i] + zz * (MAX[i] - MIN[i]);
      if (v < MIN[i]) v = MIN[i];
      else if (v > MAX[i]) v = MAX[i];
      x[i] = v;
    }
    for (let j = 0; j < 6; j++) {
      const s = (signs && typeof signs[j] === "number" && signs[j] < 0) ? -1 : 1;
      x[N + j] = s;
    }
    for (let e = 0; e < E; e++) {
      let zz = (z && typeof z[N + e] === "number" && isFinite(z[N + e])) ? clamp01(z[N + e]) : 0;
      x[N + 6 + e] = EMIN[e] + zz * (EMAX[e] - EMIN[e]);
