  function newTrace() {
    return {
      on: 1,
      n: 0,
      minH: 1e9,
      maxH: -1e9,
      maxAbsPhi: 0,
      maxAbsSpin: 0,
      sumPhi2: 0,
      sumSpin2: 0,
      sumAbsPhi: 0,
      sumHeight: 0,
      sumVx: 0,
      lowTime: 0,
      badAngleTime: 0,
      tailN: 0,
      tailPhi: 0,
      tailVx: 0,
      tailHeight: 0,
      tailAbsPhi: 0,
      finalT: 0,
      finalPhi: 0,
      finalSpin: 0,
      finalVx: 0,
      finalVy: 0,
      finalHeight: 1,
      feet: [0, 0],
      q: [0, 0]
