  function scoreResult(r, tr, x) {
    if (!r) return -1e12;
    let d = +r.distance;
    if (!isFinite(d)) d = 0;
    let tm = +r.time;
    if (!isFinite(tm)) tm = 0;
    let en = +r.energy;
    if (!isFinite(en)) en = 0;

    if (r.outcome === "invalid" || r.outcome === "error") {
