    }

    const finished = (r.outcome === "finished" || tm >= 9.95);
    let s = d;
    if (finished) s += 40;
    else s -= 25;
    s += 0.02 * Math.min(tm, 10);

    if (tr && tr.n > 0) {
      const n = tr.n;
      const rmsPhi = Math.sqrt(tr.sumPhi2 / n);
      const rmsSpin = Math.sqrt(tr.sumSpin2 / n);
      const tailN = tr.tailN > 0 ? tr.tailN : 1;
      const tailPhi = tr.tailPhi / tailN;
      const tailVx = tr.tailVx / tailN;
      const tailH = tr.tailHeight / tailN;
      const finalH = tr.finalHeight;

      s += 0.25 * Math.max(0, Math.min(3, tailVx));
      s -= 0.8 * Math.max(0, tr.maxAbsPhi - 1.0);
      s -= 2.5 * Math.max(0, 0.60 - tr.minH);
      s -= 0.04 * Math.max(0, rmsSpin - 4.0);
      s -= 1.0 * Math.max(0, Math.abs(tailPhi) - 0.85);
      s -= 0.5 * Math.max(0, 0.65 - finalH);
      s -= 0.05 * Math.max(0, tr.lowTime - 1.0);
      s -= 0.1 * Math.max(0, tr.badAngleTime - 0.8);
      s -= 0.2 * Math.max(0, tr.maxH - 1.8);
      if (tr.finalVx < -0.2) s -= 0.5 * (-tr.finalVx - 0.2);
      s += 0.02 * Math.max(0, Math.min(1.5, tailH - 0.8));
