    } catch (e) {
      r = { distance: 0, outcome: "error", time: 0, energy: 0 };
    }
    const tr = TRACE;
    TRACE = null;
    used++;

    const sc = scoreResult(r, tr, x);
    const rec = {
      x: x,
      z: z.slice(),
      signs: signs ? signs.slice() : [1, 1, 1, 1, 1, 1],
      score: sc,
      r: r,
      tr: tr
    };
    cache[key] = rec;
    allRecs.push(rec);
    if (sc > bestScoreGlobal) {
      bestScoreGlobal = sc;
      bestRecGlobal = rec;
    }
    return rec;
