  const freqVals = [1.20, 1.50, 1.70, 1.90, 2.10, 2.35, 2.65, 3.00];
  for (let k = 0; k < freqVals.length; k++) {
    const z = zKnown.slice();
    setPhys(z, 0, freqVals[k]);
    addSeed(z, knownSigns);
  }

  const dutyVals = [0.35, 0.40, 0.45, 0.50, 0.55, 0.60, 0.65];
  for (let k = 0; k < dutyVals.length; k++) {
    const z = zKnown.slice();
    setPhys(z, 1, dutyVals[k]);
    addSeed(z, knownSigns);
  }

  const phaseVals = [0.0, 0.15, 0.30, 0.50, 0.65, 0.80, 0.95];
  for (let k = 0; k < phaseVals.length; k++) {
    const z = zKnown.slice();
    setPhys(z, 2, phaseVals[k]);
    addSeed(z, knownSigns);
  }

  const strideVals = [0.15, 0.18, 0.21, 0.24, 0.27, 0.30, 0.34, 0.38, 0.44];
  for (let k = 0; k < strideVals.length; k++) {
    const z = zKnown.slice();
    setPhys(z, 3, strideVals[k]);
    addSeed(z, knownSigns);
  }

  const baseYVals = [0.62, 0.66, 0.70, 0.74, 0.77, 0.80, 0.82];
  for (let k = 0; k < baseYVals.length; k++) {
    const z = zKnown.slice();
    setPhys(z, 4, baseYVals[k]);
    addSeed(z, knownSigns);
  }

  const liftVals = [0.0, 0.05, 0.08, 0.12, 0.16, 0.22, 0.30];
