  const phiDesVals = [-0.20, -0.10, 0.0, 0.10];
  for (let k = 0; k < phiDesVals.length; k++) {
    const z = zKnown.slice();
    setPhys(z, 9, phiDesVals[k]);
    addSeed(z, knownSigns);
