  for (let k = 0; k < hTVals.length; k++) {
    const z = zKnown.slice();
    setPhys(z, 11, hTVals[k]);
    addSeed(z, knownSigns);
  }

  const kxPhiVals = [-2.5, -2.0, -1.5, -1.0, -0.5, 0.5];
  for (let k = 0; k < kxPhiVals.length; k++) {
    const z = zKnown.slice();
    setPhys(z, 13, kxPhiVals[k]);
    addSeed(z, knownSigns);
  }

  const fMults = [1.05, 1.12, 1.22, 1.35];
  const sMults = [1.08, 1.18, 1.30];
  const vAdds = [0.15, 0.35, 0.60];

  for (let fi = 0; fi < fMults.length; fi++) {
    for (let si = 0; si < sMults.length; si++) {
      for (let vi = 0; vi < vAdds.length; vi++) {
        const z = zKnown.slice();
        setPhys(z, 0, physVal(zKnown, 0) * fMults[fi]);
        setPhys(z, 3, physVal(zKnown, 3) * sMults[si]);
        setPhys(z, 10, physVal(zKnown, 10) + vAdds[vi]);
        setPhys(z, 5, physVal(zKnown, 5) + 0.02);
        addSeed(z, knownSigns);
      }
    }
  }

  for (let byi = 0; byi < 3; byi++) {
    for (let li = 0; li < 3; li++) {
      const z = zKnown.slice();
      setPhys(z, 4, [0.66, 0.70, 0.74][byi]);
      setPhys(z, 5, [0.12, 0.18, 0.24][li]);
      setPhys(z, 11, 1.10);
      addSeed(z, knownSigns);
    }
  }

  const safeSeed = zKnown.slice();
  setExtra(safeSeed, 0, 1.2);
  setExtra(safeSeed, 1, 0.4);
  setExtra(safeSeed, 2, 0.4);
  setExtra(safeSeed, 3, 0.12);
  setExtra(safeSeed, 4, 0);
  addSeed(safeSeed, knownSigns);

  const e0Vals = [0.4, 0.8, 1.2, 1.6];
  const e1Vals = [0.0, 0.25, 0.45];
  for (let e0i = 0; e0i < e0Vals.length; e0i++) {
    for (let e1i = 0; e1i < e1Vals.length; e1i++) {
      const z = zKnown.slice();
      setExtra(z, 0, e0Vals[e0i]);
      setExtra(z, 1, e1Vals[e1i]);
      setExtra(z, 2, 0.2);
      setExtra(z, 3, 0.08);
      setExtra(z, 4, 0);
      addSeed(z, knownSigns);
    }
  }

  const hopE0 = [0.8, 1.2];
  const hopE1 = [0.30, 0.50];
  const hopE3 = [0.08, 0.15];
  for (let i0 = 0; i0 < hopE0.length; i0++) {
    for (let i1 = 0; i1 < hopE1.length; i1++) {
      for (let i3 = 0; i3 < hopE3.length; i3++) {
        const z = zKnown.slice();
        setPhys(z, 4, Math.max(0.62, physVal(zKnown, 4) - 0.03));
        setPhys(z, 5, physVal(zKnown, 5) + 0.06);
        setPhys(z, 3, physVal(zKnown, 3) * 1.12);
        setExtra(z, 0, hopE0[i0]);
        setExtra(z, 1, hopE1[i1]);
        setExtra(z, 2, 0.35);
        setExtra(z, 3, hopE3[i3]);
        addSeed(z, knownSigns);
      }
