  }

  let seedRecs = [];
  for (let si = 0; si < seedList.length; si++) {
    if (trialsLeft() <= 0 || !timeOK()) break;
    const rec = evalZ(seedList[si].z, seedList[si].signs);
    if (rec) seedRecs.push(rec);
  }

  seedRecs.sort((a, b) => b.score - a.score);

  const sig0 = new Array(DIM);
  for (let i = 0; i < N; i++) {
    let s = 0.12;
    if (i < 6) s = 0.10;
    if (i === 2) s = 0.16;
    if (i === 10 || i === 11) s = 0.12;
    if (i === 20 || i === 22) s = 0.10;
    if (i === 26 || i === 27 || i === 28 || i === 32) s = 0.14;
    sig0[i] = s;
  }
  for (let e = 0; e < E; e++) sig0[N + e] = 0.18;

  function makeState(rec) {
    return {
      mean: rec.z.slice(),
      bestZ: rec.z.slice(),
      bestScore: rec.score,
      bestX: rec.x.slice(),
      signs: rec.signs.slice(),
