  let states = [];
  const seenKeys = Object.create(null);
  for (let i = 0; i < seedRecs.length && states.length < 8; i++) {
    const rec = seedRecs[i];
    const k = xKey(rec.x);
    if (seenKeys[k]) continue;
    seenKeys[k] = 1;
