  let gen = 0;
  while (states.length > 0 && gen < 80 && trialsLeft() > 80 && timeOK()) {
    if (gen === 8 && states.length > 4) states = states.slice(0, 4);
    if (gen === 20 && states.length > 2) states = states.slice(0, 2);

    const popPer = states.length <= 2 ? 10 : 6;

    for (let si = 0; si < states.length; si++) {
