      const newSig = new Array(DIM);
      for (let i = 0; i < DIM; i++) {
        let v = 0;
        for (let e = 0; e < maxElite; e++) {
          const d = recs[e].z[i] - newMean[i];
          v += weights[e] * d * d;
        }
