  let localIter = 0;

  while (trialsLeft() > 0 && timeOK() && localIter < 700 && bestRecGlobal) {
    localIter++;

    const baseRec = bestRecGlobal;
    const z = baseRec.z.slice();

    if (Math.random() < 0.55) {
      for (let i = 0; i < DIM; i++) {
        if (Math.random() < 0.70) {
