          }
          if (i >= N) mult = 1.0;
          z[i] = clamp01(z[i] + localSigma * mult * gauss());
        }
      }
    } else {
      const cnt = 1 + ((Math.random() * 3) | 0);
      for (let c = 0; c < cnt; c++) {
        const i = (Math.random() * DIM) | 0;
        let step = localSigma * (0.5 + Math.random());
        if (Math.random() < 0.5) step = -step;
        z[i] = clamp01(z[i] + step);
      }
      if (Math.random() < 0.25) {
        const e = (Math.random() * E) | 0;
        let step = localSigma * (0.5 + Math.random());
        if (Math.random() < 0.5) step = -step;
        z[N + e] = clamp01(z[N + e] + step);
