    }

    const rec = evalZ(z, baseRec.signs);
    if (rec && rec.score > baseRec.score + 1e-9) {
      localSigma = Math.max(0.012, localSigma * 0.94);
    } else {
      localSigma *= 0.997;
      if (localSigma < 0.012) localSigma = 0.060;
    }
  }

  TRACE = null;

  function isFinishedRec(rec) {
    return rec && rec.r &&
      (rec.r.outcome === "finished" || (+rec.r.time >= 9.90));
  }

  function robustVal(x) {
    const e0 = clampF(x[N + 6], 0, 3);
    const e1 = clampF(x[N + 7], 0, 1);
    const e2 = clampF(x[N + 8], 0, 2);
    const e3 = clampF(x[N + 9], 0, 0.4);
    const e4 = x[N + 10] || 0;

    let v = 0;
    v += 1.0 * Math.min(e0, 1.2);
    v -= 0.25 * Math.max(0, e0 - 1.5);
    v += 0.8 * Math.min(e1, 0.5);
    v -= 0.4 * Math.max(0, e1 - 0.65);
    v += 0.2 * Math.min(e2, 0.6);
    v -= 0.1 * Math.max(0, e2 - 0.9);
    v += 0.8 * Math.min(e3, 0.15);
    v -= 0.5 * Math.max(0, e3 - 0.22);
    v += 0.0005 * Math.min(40, Math.abs(e4));
    return v;
  }

  let glob = null;
  for (let i = 0; i < allRecs.length; i++) {
    if (!glob || allRecs[i].score > glob.score) glob = allRecs[i];
  }
  if (!glob) glob = evalZ(zKnown, knownSigns);

  let chosen = glob;
  if (glob) {
    const topScore = glob.score;
    let currentRob = robustVal(glob.x);

    for (let i = 0; i < allRecs.length; i++) {
      const rec = allRecs[i];
      if (!rec || !isFinishedRec(rec)) continue;
      if (rec.score < topScore - 0.35) continue;
      const rv = robustVal(rec.x);
      if (rv > currentRob + 1e-9 ||
          (Math.abs(rv - currentRob) <= 1e-9 && rec.score > chosen.score + 1e-9)) {
        currentRob = rv;
        chosen = rec;
      }
    }
  }

  if (chosen && chosen.x && chosen.x.length >= LEN) return chosen.x.slice();
  if (glob && glob.x) return glob.x.slice();
  return KNOWN_X.slice();
}

