function clampF(x, a, b) {
  if (typeof x !== "number" || !isFinite(x)) return a;
  return x < a ? a : (x > b ? b : x);
}

function clamp01(x) {
  if (typeof x !== "number" || !isFinite(x)) return 0;
  return x < 0 ? 0 : (x > 1 ? 1 : x);
}

function wrap1(x) {
  x = x % 1;
  if (x < 0) x += 1;
  return x;
}

function solveIK(x, yd) {
  if (yd < 0.05) yd = 0.05;
  let r2 = x * x + yd * yd;
  const rMin = Math.abs(L1 - L2) + 0.025;
  const rMax = L1 + L2 - 0.004;

  if (r2 > rMax * rMax) {
    const s = rMax / Math.sqrt(r2 + 1e-12);
    x *= s;
    yd *= s;
    r2 = rMax * rMax;
  } else if (r2 < rMin * rMin) {
    const s = rMin / Math.sqrt(Math.max(r2, 1e-12));
    x *= s;
    yd *= s;
    r2 = rMin * rMin;
  }

  let c = (r2 - L1 * L1 - L2 * L2) / (2 * L1 * L2);
  c = clampF(c, -1, 1);
  const k = -Math.acos(c);
  const beta = Math.atan2(L2 * Math.sin(k), L1 + L2 * Math.cos(k));
  const gamma = Math.atan2(x, yd);
  return [gamma - beta, k];
}

function sampleGround4(d, h1, h2, h3, h4) {
  if (!isFinite(d) || d <= 0) return 0;
  if (d < 0.5) return h1 * (d / 0.5);
  if (d < 1) return h1 + (h2 - h1) * ((d - 0.5) / 0.5);
  if (d < 2) return h2 + (h3 - h2) * (d - 1);
  if (d < 4) return h3 + (h4 - h3) * ((d - 2) / 2);
  return h4;
}

function maxGround4(d, look, h1, h2, h3, h4) {
  let m = sampleGround4(d, h1, h2, h3, h4);
  let v = sampleGround4(d + look * 0.5, h1, h2, h3, h4);
  if (v > m) m = v;
  v = sampleGround4(d + look, h1, h2, h3, h4);
  if (v > m) m = v;
  v = sampleGround4(d + look * 1.5, h1, h2, h3, h4);
  if (v > m) m = v;
  return m;
}

