  const KbPhi = clampF(av(16, -80), -400, 400);
  const KbSpin = clampF(av(17, -15), -200, 200);
  const KbV = clampF(av(18, 8), -300, 300);
  const wSwing = clampF(av(19, 0.5), 0.0, 2.0);

  const kpH = clampF(av(20, 220), 0, 800);
  const kdH = clampF(av(21, 12), 0, 150);
  const kpK = clampF(av(22, 220), 0, 800);
  const kdK = clampF(av(23, 12), 0, 150);
  const kneeStance = clampF(av(24, 0.0), -1.0, 1.0);
  const contactAdj = Math.max(0, clampF(av(25, 0.02), 0, 0.2));
  const terrainLiftGain = Math.max(0, clampF(av(26, 0.5), 0, 2.0));
  const terrainHip = clampF(av(27, 0.2), -2.0, 2.0);
  const ffHip = clampF(av(28, 0.0), -1.5, 1.5);
  const ffKnee = clampF(av(29, 0.0), -1.5, 1.5);
  const rampT = clampF(av(30, 0.35), 0.02, 1.5);
  const stanceBounce = clampF(av(31, 0.0), -0.4, 0.4);
  const kneeSwingExtra = clampF(av(32, 0.0), -1.0, 1.0);

  const stanceAnchor = clampF(ex(0, 0), 0, 1);
  const strideVel = clampF(ex(1, 0), -0.8, 0.8);
  const strideGeom = clampF(ex(2, 0), 0, 1);
  const freqVel = clampF(ex(3, 0), -1.5, 1.5);
  const freqTerrain = clampF(ex(4, 0), -1, 2);
  const dutyVel = clampF(ex(5, 0), -0.4, 0.4);
  const footVelGain = clampF(ex(6, 0), -1, 1);
  const hipPushGain = clampF(ex(7, 0), -200, 200);
  const kneePushGain = clampF(ex(8, 0), -200, 200);
  const pushPhase = clampF(ex(9, 0), 0, 1);
  const heightVyGain = clampF(ex(10, 0), -3, 3);
  const heightSpinGain = clampF(ex(11, 0), -2, 2);
  const groundGain = clampF(ex(12, 0), -0.5, 1.5);
  const swingClearGain = clampF(ex(13, 0), 0, 3);
  const pathClearGain = clampF(ex(14, 0), 0, 3);
  const lookahead = clampF(ex(15, 0), 0, 0.6);
  const hurdleStrideReduce = clampF(ex(16, 0), 0, 1);
  const hurdleLiftGain = clampF(ex(17, 0), 0, 3);
  const hurdleHipGain = clampF(ex(18, 0), -0.4, 0.4);
  const contactPhaseGain = clampF(ex(19, 0), 0, 1);
  const contactLiftGain = clampF(ex(20, 0), 0, 1);
  const heightPitchGain = clampF(ex(21, 0), -2, 2);
  const stanceKneeVel = clampF(ex(22, 0), -1.5, 1.5);
  const bodyHurdleGain = clampF(ex(23, 0), -0.3, 0.5);

  if (!M.init || (typeof M.lastT === "number" && t < M.lastT - 0.05)) {
    M.init = 1;
    M.lastT = t;
    M.q = [0, wrap1(phaseOff)];
    M.initH = [hips[0], hips[1]];
    M.initK = [knees[0], knees[1]];
    M.slow = 0;
    M.x = 0;
    M.lastKick = -10;
    M.kickUntil = -1;
    M.prevStance = [0, 0];
    M.anchorX = [0, 0];
  }

  let dt = 1 / 60;
  if (typeof M.lastT === "number") {
    const dd = t - M.lastT;
    if (dd > 0 && dd < 0.2) dt = dd;
  }
  M.lastT = t;

  const rr = clamp01(t / rampT);
  const ramp = rr * rr * (3 - 2 * rr);

  M.x += vx * dt;

  if (t > 0.9 && t < 19.5) {
    if (Math.abs(vx) < 0.05 && height < 1.0) M.slow += dt;
    else M.slow = Math.max(0, M.slow - dt * 2.5);
  } else {
    M.slow = 0;
  }

  if (M.slow > 0.9 && t > M.lastKick + 1.2 && t < 18.5) {
    M.kickUntil = t + 0.9;
    M.lastKick = t;
    M.slow = 0;
    M.q[0] = 0;
    M.q[1] = phaseOff;
    M.prevStance = [0, 0];
  }

  const kick = t < M.kickUntil ? 1 : 0;
  const need = clampF(vDes0 - vx, -2.5, 2.5);
  const vErr = vx - vDes0;

  let fUse = freq0 * (1 + clampF(freqVel * need, -0.7, 0.9) + clampF(freqTerrain * prep, -0.5, 1.2));
  if (kick) fUse *= 1.35;
  fUse = clampF(fUse, 0.45, 4.8);

  let dutyUse = duty0 + clampF(dutyVel * need, -0.28, 0.28);
  dutyUse = clampF(dutyUse, 0.20, 0.86);

  const phaseScale = ramp < 1 ? (0.25 + 0.75 * ramp) : 1;
  M.q[0] = wrap1(M.q[0] + fUse * dt * phaseScale);
  M.q[1] = wrap1(M.q[1] + fUse * dt * phaseScale);

  let em = 0;
  if (t > 0.4) {
    if (height < 0.62) em = Math.max(em, (0.62 - height) / 0.25);
    if (Math.abs(phi) > 0.85 && height < 1.0) em = Math.max(em, (Math.abs(phi) - 0.85) / 0.5);
    if (Math.abs(spin) > 5.0) em = Math.max(em, (Math.abs(spin) - 5.0) / 9.0);
  }
  em = clampF(em, 0, 1);

  let yBase = baseY + Kh * (heightTarget - height);
  yBase += heightVyGain * (-vy);
  yBase += heightSpinGain * spin;
  yBase -= heightPitchGain * Math.abs(phi);
  yBase += bodyHurdleGain * prep;
  if (em > 0) yBase = Math.max(yBase, 0.74 + 0.06 * em);

  let phiDes = phiDes0;
  const ePhi = phi - phiDes;
  let xBal = KxPhi * ePhi + KxSpin * spin + KxV * vErr;
  xBal += footVelGain * clampF(vErr, -2, 2);
  let balT = KbPhi * ePhi + KbSpin * spin + KbV * vErr;
  balT += ffHip * 0;
  if (em > 0) {
    balT *= (1 + 0.55 * em);
    xBal *= (1 - 0.35 * em);
  }

  const geomStride = Math.max(0.015, Math.abs(vx) * dutyUse / (2 * Math.max(fUse, 0.2)));
  let strideUse = stride0 + strideVel * clampF(need, -1.5, 1.5);
  if (strideGeom > 0) strideUse = (1 - strideGeom) * strideUse + strideGeom * geomStride;
  if (hurdleStrideReduce > 0) strideUse *= (1 - hurdleStrideReduce * prep);
  if (kick) strideUse *= 1.30;
  if (em > 0) strideUse *= (1 - 0.70 * em);
  strideUse = clampF(strideUse, 0.01, 0.75);

  const liftUse = lift0 * (1 + 0.6 * kick);

  const out = [0, 0, 0, 0];

  for (let i = 0; i < 2; i++) {
    let q = wrap1(M.q[i]);
    let isStance = q < dutyUse;

    if (t > rampT + 0.12) {
      const denS = 1 - dutyUse;
      if (!isStance && feet[i] > 0.5 && denS > 1e-4) {
        const us = (q - dutyUse) / denS;
        if (us > 0.75 && us < 1.001) {
          q = 0;
          isStance = true;
        }
      } else if (isStance && feet[i] < 0.5 && q > 0.95 * dutyUse) {
        q = dutyUse + 1e-5;
        isStance = false;
      }
    }

    M.q[i] = wrap1(q);

    let u = 0;
    let xPhase = 0;
    let liftAmt = 0;

    if (isStance) {
      u = clampF(q / Math.max(dutyUse, 1e-5), 0, 1);
      xPhase = strideUse * (1 - 2 * u);
    } else {
      const den = Math.max(1 - dutyUse, 1e-4);
      u = clampF((q - dutyUse) / den, 0, 1);
      const sm = u * u * (3 - 2 * u);
      xPhase = strideUse * (-1 + 2 * sm);
      liftAmt = Math.sin(Math.PI * u);
      if (liftAmt < 0) liftAmt = 0;
    }

    const entered = isStance && !M.prevStance[i];
    if (entered) M.anchorX[i] = M.x + xPhase;

    let xVal = xPhase;
    if (isStance && stanceAnchor > 0) {
      let xAnchor = M.anchorX[i] - M.x;
      xAnchor = clampF(xAnchor, -0.8, 0.8);
      xVal = (1 - stanceAnchor) * xPhase + stanceAnchor * xAnchor;
    }

    let xDes = xVal + xBal + terrainHip * terr * liftAmt;
    xDes += hurdleHipGain * prep * (isStance ? 0.3 : 1.0) * liftAmt;
    if (em > 0) xDes *= (1 - 0.4 * em);

    let yDes = yBase;

    if (isStance) {
      yDes += stanceBounce * Math.sin(Math.PI * u);
      if (feet[i] < 0.5) yDes += contactAdj * (1 + 0.5 * (1 - u));
    } else {
      yDes -= (liftUse + terrainLiftGain * terr) * liftAmt;
      if (feet[i] > 0.5) yDes -= contactAdj * 0.5;
    }

    const xTerr = Math.max(0, xDes);
    const gAt = sampleGround4(xTerr, h1, h2, h3, h4);
    const gPath = maxGround4(xTerr, lookahead, h1, h2, h3, h4);
    const gAtPos = Math.max(0, gAt);
    const gPathPos = Math.max(0, gPath);
    const excess = Math.max(0, gPathPos - gAtPos);

    if (groundGain !== 0) yDes -= groundGain * gAt;

    if (!isStance) {
      if (swingClearGain > 0) yDes -= swingClearGain * excess * (0.5 + 0.5 * liftAmt);
      if (pathClearGain > 0) yDes -= pathClearGain * gPathPos * liftAmt;
      if (hurdleLiftGain > 0) yDes -= hurdleLiftGain * prep * Math.sqrt(liftAmt);
      if (contactLiftGain > 0 && feet[i] > 0.5 && u < 0.85) {
        yDes -= contactLiftGain * (1 - u) * 0.12;
      }
    } else {
      if (hurdleLiftGain > 0) yDes -= hurdleLiftGain * prep * 0.18 * (1 - u);
    }

    if (em > 0) yDes += 0.10 * em;
    yDes = clampF(yDes, 0.15, 0.818);

    const sol = solveIK(xDes, yDes);
    let targetH = hMap * sol[0] - cTorso * phi + hipBias;
    let targetK = kMap * sol[1] + kneeBias;

    if (isStance) {
      targetK += kneeStance * (1 - u);
      if (stanceKneeVel !== 0) targetK += stanceKneeVel * clampF(need, -1.5, 1.5) * (1 - u);
    } else {
      targetK -= kneeSwingExtra * liftAmt;
    }
    if (em > 0) targetK += 0.12 * em;
    if (prep > 0) targetK -= 0.10 * prep * (isStance ? 0.3 : liftAmt);

    targetH = clampF(targetH, -0.89, 1.19);
    targetK = clampF(targetK, -1.68, -0.055);

    if (ramp < 1) {
      const ih = (M.initH && typeof M.initH[i] === "number") ? M.initH[i] : targetH;
      const ik = (M.initK && typeof M.initK[i] === "number") ? M.initK[i] : targetK;
      targetH = ih + (targetH - ih) * ramp;
      targetK = ik + (targetK - ik) * ramp;
    }

    const weight = isStance ? 1.0 : wSwing;
    let hipU = kpH * (targetH - hips[i]) - kdH * hipSpds[i] + balT * weight + ffHip * 210;
    let kneeU = kpK * (targetK - knees[i]) - kdK * kneeSpds[i] + ffKnee * 172 + 35 * em;

    const sH = i === 0 ? sHA : sHB;
    const sK = i === 0 ? sKA : sKB;

    if (hipPushGain !== 0 || kneePushGain !== 0) {
      let pushShape = 0;
      if (isStance) {
        const pp = 1 + Math.max(0, pushPhase);
        pushShape = 0.20 + 0.80 * Math.pow(u, pp);
      }
      const pushVal = pushShape * clampF(need, -2.0, 2.0);
      if (hipPushGain !== 0) hipU += sH * hipPushGain * pushVal;
      if (kneePushGain !== 0) kneeU += sK * kneePushGain * pushVal;
    }

    if (!isFinite(hipU)) hipU = 0;
    if (!isFinite(kneeU)) kneeU = 0;

    let ho = sH * hipU / 210;
    let ko = sK * kneeU / 172;

    if (!isFinite(ho)) ho = 0;
    if (!isFinite(ko)) ko = 0;
    if (ho > 1) ho = 1;
    else if (ho < -1) ho = -1;
    if (ko > 1) ko = 1;
    else if (ko < -1) ko = -1;

    out[2 * i] = ho;
    out[2 * i + 1] = ko;
    M.prevStance[i] = isStance ? 1 : 0;
  }

  if (TRACE && TRACE.on) {
    const T = TRACE;
    T.n++;
    const ap = Math.abs(phi);
    const asp = Math.abs(spin);
    T.sumPhi2 += phi * phi;
    T.sumSpin2 += spin * spin;
    T.sumAbsPhi += ap;
    T.sumHeight += height;
    T.sumVx += vx;
    T.sumVx2 += vx * vx;
    if (height < T.minH) T.minH = height;
    if (height > T.maxH) T.maxH = height;
    if (ap > T.maxAbsPhi) T.maxAbsPhi = ap;
    if (asp > T.maxAbsSpin) T.maxAbsSpin = asp;
    if (height < 0.58) T.lowTime += dt;
    if (ap > 1.0) T.badAngleTime += dt;
    if (t > 8) {
      T.tailN++;
      T.tailPhi += phi;
      T.tailVx += vx;
      T.tailHeight += height;
      T.tailAbsPhi += ap;
      T.tailPhi2 += phi * phi;
      T.tailVx2 += vx * vx;
    }
    T.finalT = t;
    T.finalPhi = phi;
    T.finalSpin = spin;
    T.finalVx = vx;
    T.finalVy = vy;
    T.finalHeight = height;
    T.feet = [feet[0], feet[1]];
    T.q = [M.q[0], M.q[1]];
  }

  return out;
}

function learn(lab) {
  const tStart = (typeof Date !== "undefined" && Date.now) ? Date.now() : 0;
  let used = 0;

  const cache = Object.create(null);
  const allRecs = [];
  let bestScoreGlobal = -1e100;
  let bestRecGlobal = null;

  function timeOK() {
    if (!tStart) return true;
    return (Date.now() - tStart) < 166000;
  }

  function trialsLeft() {
    try {
      if (lab && typeof lab.trialsLeft === "function") {
        const n = lab.trialsLeft();
        if (typeof n === "number" && isFinite(n)) return n;
      }
    } catch (e) {}
    return 1000 - used;
  }

  function gauss() {
    let u = Math.random();
    if (u < 1e-12) u = 1e-12;
    let v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  function xKey(x) {
    let s = "";
    for (let i = 0; i < x.length; i++) {
      let v = x[i];
      if (typeof v !== "number" || !isFinite(v)) v = 0;
      s += (Math.round(v * 1000000) / 1000000) + ",";
    }
    return s;
  }

  function zFromX(x) {
    const z = new Array(DIM);
    for (let i = 0; i < N; i++) {
      let v = (x && typeof x[i] === "number" && isFinite(x[i])) ? x[i] : DEF_MAIN[i];
      z[i] = clamp01((v - MIN[i]) / (MAX[i] - MIN[i]));
    }
    for (let e = 0; e < E; e++) {
      const idx = N + 6 + e;
      let v = (x && typeof x[idx] === "number" && isFinite(x[idx])) ? x[idx] : EDEF[e];
      z[N + e] = clamp01((v - EMIN[e]) / (EMAX[e] - EMIN[e]));
    }
    return z;
  }

  function signsFromX(x) {
    const s = new Array(6);
    for (let j = 0; j < 6; j++) {
      const idx = N + j;
      s[j] = (x && typeof x[idx] === "number" && x[idx] < 0) ? -1 : 1;
    }
    return s;
  }

  function decode(z, signs) {
    const x = new Array(LEN);
    for (let i = 0; i < N; i++) {
      const zz = clamp01(z && typeof z[i] === "number" ? z[i] : 0);
      let v = MIN[i] + zz * (MAX[i] - MIN[i]);
      if (v < MIN[i]) v = MIN[i];
      else if (v > MAX[i]) v = MAX[i];
      x[i] = v;
    }
    for (let j = 0; j < 6; j++) {
      x[N + j] = (signs && typeof signs[j] === "number" && signs[j] < 0) ? -1 : 1;
    }
    for (let e = 0; e < E; e++) {
      const zz = clamp01(z && typeof z[N + e] === "number" ? z[N + e] : 0);
      x[N + 6 + e] = EMIN[e] + zz * (EMAX[e] - EMIN[e]);
    }
    return x;
  }

  function setP(z, i, v) {
    z[i] = clamp01((v - MIN[i]) / (MAX[i] - MIN[i]));
  }

  function getP(z, i) {
    return MIN[i] + clamp01(z[i]) * (MAX[i] - MIN[i]);
  }

  function setE(z, e, v) {
    z[N + e] = clamp01((v - EMIN[e]) / (EMAX[e] - EMIN[e]));
  }

  function getE(z, e) {
    return EMIN[e] + clamp01(z[N + e]) * (EMAX[e] - EMIN[e]);
  }

  const zKnown = zFromX(KNOWN_X);
  const signsKnown = signsFromX(KNOWN_X);
  const zAtt4 = zFromX(ATT4_X);
  const signsAtt4 = signsFromX(ATT4_X);
  const zDef = zFromX(DEF_X);
  const signsDef = signsFromX(DEF_X);

  function addRobustExtras(z) {
    setE(z, 12, 0.80);
    setE(z, 13, 0.85);
    setE(z, 14, 0.35);
    setE(z, 15, 0.12);
    setE(z, 16, 0.35);
    setE(z, 17, 0.85);
    setE(z, 23, 0.05);
  }

  function newTrace() {
    return {
      on: 1,
      n: 0,
      minH: 1e9,
      maxH: -1e9,
      maxAbsPhi: 0,
      maxAbsSpin: 0,
      sumPhi2: 0,
      sumSpin2: 0,
      sumAbsPhi: 0,
      sumHeight: 0,
      sumVx: 0,
      sumVx2: 0,
      lowTime: 0,
      badAngleTime: 0,
      tailN: 0,
      tailPhi: 0,
      tailVx: 0,
      tailHeight: 0,
      tailAbsPhi: 0,
      tailPhi2: 0,
      tailVx2: 0,
      finalT: 0,
      finalPhi: 0,
      finalSpin: 0,
      finalVx: 0,
      finalVy: 0,
      finalHeight: 1,
      feet: [0, 0],
      q: [0, 0]
    };
  }

  function tailVx(tr) {
    if (!tr || !tr.tailN) return 0;
    return tr.tailVx / tr.tailN;
  }

  function scoreResult(r, tr) {
    if (!r) return -1e12;
    let d = +r.distance;
    if (!isFinite(d)) d = 0;
    let tm = +r.time;
    if (!isFinite(tm)) tm = 0;
    let en = +r.energy;
    if (!isFinite(en)) en = 0;

    if (r.outcome === "invalid" || r.outcome === "error") {
      return -1e10 + d;
    }

    const finished = (r.outcome === "finished" || tm >= 9.95);
    let s = d;
    if (finished) s += 3.2;
    else s -= 5.0 * Math.max(0, 1 - tm / 10);

    if (tr && tr.n > 0) {
      const n = tr.n;
      const rmsPhi = Math.sqrt(tr.sumPhi2 / n);
      const rmsSpin = Math.sqrt(tr.sumSpin2 / n);
      const tv = tailVx(tr);

      s += 0.35 * Math.max(0, Math.min(2.0, tv));
      s -= 1.2 * Math.max(0, tr.maxAbsPhi - 1.0);
      s -= 2.8 * Math.max(0, 0.58 - tr.minH);
      s -= 0.5 * Math.max(0, tr.lowTime - 0.65);
      s -= 0.04 * Math.max(0, tr.maxAbsSpin - 12);
      s -= 0.35 * Math.max(0, rmsPhi - 0.8);
      s -= 0.05 * Math.max(0, rmsSpin - 5.0);
      s -= 0.8 * Math.max(0, 0.65 - tr.finalHeight);
      s -= 0.5 * Math.max(0, Math.abs(tr.finalPhi) - 0.95);
      s -= 0.15 * Math.max(0, tr.maxH - 2.0);
    }

    s -= 0.000002 * Math.max(0, en);
    return s;
  }

  function evalZ(z, signs) {
    if (!z || z.length < DIM) return null;
    const x = decode(z, signs);
    const key = xKey(x);

    if (cache[key] !== undefined) return cache[key];
    if (trialsLeft() <= 0 || !timeOK()) return null;

    TRACE = newTrace();
    let r;
    try {
      r = lab.trial(x);
    } catch (e) {
      r = { distance: 0, outcome: "error", time: 0, energy: 0 };
    }
    const tr = TRACE;
    TRACE = null;
    used++;

    const sc = scoreResult(r, tr);
    const rec = {
      x: x,
      z: z.slice(),
      signs: signs ? signs.slice() : [1, 1, 1, 1, 1, 1],
      score: sc,
      r: r,
      tr: tr,
      key: key
    };

    cache[key] = rec;
    allRecs.push(rec);

    if (sc > bestScoreGlobal) {
      bestScoreGlobal = sc;
      bestRecGlobal = rec;
    }
    return rec;
  }

  function isFinishedRec(rec) {
    return rec && rec.r && (rec.r.outcome === "finished" || (+rec.r.time >= 9.90));
  }

  function robustVal(rec) {
    if (!rec) return -1e12;
    const r = rec.r || {};
    const tr = rec.tr || newTrace();
    let s = rec.score;

    if (!isFinishedRec(rec)) s -= 8.0;

    s -= 2.4 * Math.max(0, tr.maxAbsPhi - 1.0);
    s -= 3.6 * Math.max(0, 0.58 - tr.minH);
    s -= 1.0 * Math.max(0, 0.65 - tr.finalHeight);
    s -= 1.1 * Math.max(0, Math.abs(tr.finalPhi) - 0.90);
    s -= 0.006 * Math.max(0, tr.maxAbsSpin - 12);
    s += 0.35 * Math.max(0, Math.min(2.0, tailVx(tr)));
    return s;
  }

  const elites = [];

  function insertElite(rec) {
    if (!rec) return;
    for (let i = 0; i < elites.length; i++) {
      if (elites[i].key === rec.key) return;
    }
    elites.push(rec);
    elites.sort((a, b) => b.score - a.score);
    if (elites.length > 28) elites.length = 28;
  }

  let knownRec = evalZ(zKnown, signsKnown);
  if (knownRec) insertElite(knownRec);

  const seedList = [];

  function addSeed(z, signs) {
    const zz = new Array(DIM);
    for (let i = 0; i < DIM; i++) {
      zz[i] = (z && typeof z[i] === "number" && isFinite(z[i])) ? clamp01(z[i]) : 0;
    }
    const ss = new Array(6);
    for (let j = 0; j < 6; j++) {
      ss[j] = (signs && typeof signs[j] === "number" && signs[j] < 0) ? -1 : 1;
    }
    seedList.push({ z: zz, signs: ss });
  }

  addSeed(zKnown, signsKnown);
  addSeed(zAtt4, signsAtt4);
  addSeed(zDef, signsDef);

