  }

  const MUTW = new Array(DIM);
  for (let i = 0; i < DIM; i++) MUTW[i] = 0.12;
  const oldWeights = [
    0.16, 0.13, 0.18, 0.16, 0.09, 0.14, 0.13, 0.13, 0.20, 0.09, 0.16,
    0.11, 0.14, 0.21, 0.21, 0.21, 0.21, 0.21, 0.21, 0.13, 0.10, 0.10,
    0.10, 0.10, 0.11, 0.09, 0.16, 0.16, 0.16, 0.16, 0.12, 0.10, 0.14
  ];
  for (let i = 0; i < N; i++) MUTW[i] = oldWeights[i];
  const extraWeights = [
    0.16, 0.15, 0.16, 0.16, 0.14, 0.13, 0.14, 0.16, 0.16, 0.14, 0.15,
    0.14, 0.15, 0.16, 0.16, 0.14, 0.15, 0.16, 0.13, 0.12, 0.12, 0.13,
