    if (Math.random() < 0.70) setE(z, 0, Math.random() * 0.95);
    if (Math.random() < 0.58) setE(z, 1, Math.random() * 0.80 - 0.40);
    if (Math.random() < 0.52) setE(z, 2, Math.random() * 0.85);
