  for (let i = 0; i < LEN; i++) {
    if (typeof fallback[i] !== "number" || !isFinite(fallback[i])) {
      if (i < N) fallback[i] = DEF_MAIN[i];
      else if (i < N + 6) fallback[i] = KNOWN_SIGNS[i - N];
      else fallback[i] = EDEF[i - N - 6];
    }
  }
  return fallback;
}

