function clampF(x, a, b) {
  if (typeof x !== "number" || !isFinite(x)) return a;
  return x < a ? a : (x > b ? b : x);
}

function clamp01(x) {
  if (typeof x !== "number" || !isFinite(x)) return 0;
  return x < 0 ? 0 : (x > 1 ? 1 : x);
}

function wrap1(x) {
  x = x % 1;
  if (x < 0) x += 1;
  return x;
}

function solveIK(x, yd) {
  if (yd < 0.05) yd = 0.05;
  let r2 = x * x + yd * yd;
  const rMin = Math.abs(L1 - L2) + 0.025;
  const rMax = L1 + L2 - 0.004;

  if (r2 > rMax * rMax) {
    const s = rMax / Math.sqrt(r2 + 1e-12);
    x *= s;
    yd *= s;
    r2 = rMax * rMax;
  } else if (r2 < rMin * rMin) {
    const s = rMin / Math.sqrt(Math.max(r2, 1e-12));
    x *= s;
    yd *= s;
    r2 = rMin * rMin;
  }

  let c = (r2 - L1 * L1 - L2 * L2) / (2 * L1 * L2);
  c = clampF(c, -1, 1);
  const k = -Math.acos(c);
  const beta = Math.atan2(L2 * Math.sin(k), L1 + L2 * Math.cos(k));
  const gamma = Math.atan2(x, yd);
  return [gamma - beta, k];
}

function sampleGround4(d, h1, h2, h3, h4) {
  if (!isFinite(d) || d <= 0) return 0;
  if (d < 0.5) return h1 * (d / 0.5);
  if (d < 1) return h1 + (h2 - h1) * ((d - 0.5) / 0.5);
  if (d < 2) return h2 + (h3 - h2) * (d - 1);
  if (d < 4) return h3 + (h4 - h3) * ((d - 2) / 2);
  return h4;
}

function maxGround4(d, look, h1, h2, h3, h4) {
  let m = sampleGround4(d, h1, h2, h3, h4);
  let v = sampleGround4(d + look * 0.5, h1, h2, h3, h4);
  if (v > m) m = v;
  v = sampleGround4(d + look, h1, h2, h3, h4);
  if (v > m) m = v;
  v = sampleGround4(d + look * 1.5, h1, h2, h3, h4);
  if (v > m) m = v;
  return m;
}

function packX(main, signs, old, extraNew) {
  const x = new Array(LEN);
  for (let i = 0; i < N; i++) {
    x[i] = (main && typeof main[i] === "number" && isFinite(main[i])) ? main[i] : DEF_MAIN[i];
  }
  for (let j = 0; j < 6; j++) {
    x[N + j] = (signs && typeof signs[j] === "number" && signs[j] < 0) ? -1 : 1;
  }
  for (let e = 0; e < 24; e++) {
    x[N + 6 + e] = (old && typeof old[e] === "number" && isFinite(old[e])) ? old[e] : 0;
  }
  for (let e = 0; e < 12; e++) {
    x[N + 6 + 24 + e] = (extraNew && typeof extraNew[e] === "number" && isFinite(extraNew[e])) ? extraNew[e] : 0;
  }
  return x;
}

const BASE_X = packX(BASE_MAIN, BASE_SIGNS, BASE_OLD, null);
const KNOWN_X = packX(KNOWN_MAIN, KNOWN_SIGNS, null, null);
const ATT4_X = packX(ATT4_MAIN, ATT4_SIGNS, null, null);
const DEF_X = packX(DEF_MAIN, DEF_SIGNS, null, null);

function newTrace() {
  return {
    on: 1,
    n: 0,
    minH: 1e9,
    maxH: -1e9,
    maxAbsPhi: 0,
    maxAbsSpin: 0,
    sumPhi2: 0,
    sumSpin2: 0,
    sumAbsPhi: 0,
    sumHeight: 0,
    sumVx: 0,
    sumVx2: 0,
    lowTime: 0,
    badAngleTime: 0,
    tailN: 0,
    tailPhi: 0,
    tailVx: 0,
    tailHeight: 0,
    tailAbsPhi: 0,
    tailPhi2: 0,
    tailVx2: 0,
    finalT: 0,
    finalPhi: 0,
    finalSpin: 0,
    finalVx: 0,
    finalVy: 0,
    finalHeight: 1,
    feet: [0, 0],
    q: [0, 0]
  };
}

function policy(obs, params, mem) {
  const o = obs || [];

  let a = params;
  if (params && !Array.isArray(params) && params.x && Array.isArray(params.x)) a = params.x;
  if (!Array.isArray(a) || a.length < N) a = BASE_X;

  function num(v, d) {
    return (typeof v === "number" && isFinite(v)) ? v : d;
  }
  function av(i, d) {
    return (a.length > i) ? num(a[i], d) : d;
  }
  function sg(j, d) {
    const idx = N + j;
    if (a.length > idx) {
      const v = num(a[idx], d);
      return v < 0 ? -1 : 1;
    }
    return d;
  }
  function ex(i, d) {
    const idx = N + 6 + i;
    if (a.length > idx) return clampF(num(a[idx], d), EMIN[i], EMAX[i]);
    return d;
  }

  const sHA = sg(0, BASE_SIGNS[0]);
  const sHB = sg(1, BASE_SIGNS[1]);
  const sKA = sg(2, BASE_SIGNS[2]);
  const sKB = sg(3, BASE_SIGNS[3]);
  const hMap = sg(4, BASE_SIGNS[4]);
  const kMap = sg(5, BASE_SIGNS[5]);

  const t = num(o[19], 0);
  const phi = num(o[0], 0);
  const spin = num(o[1], 0);
  const vx = num(o[2], 0);
  const vy = num(o[3], 0);
  const height = num(o[4], 1.1);

  const hips = [num(o[5], 0), num(o[10], 0)];
  const hipSpds = [num(o[6], 0), num(o[11], 0)];
  const knees = [num(o[7], 0), num(o[12], 0)];
  const kneeSpds = [num(o[8], 0), num(o[13], 0)];
  const feet = [num(o[9], 0) > 0.5 ? 1 : 0, num(o[14], 0) > 0.5 ? 1 : 0];

  const h1 = num(o[15], 0);
  const h2 = num(o[16], 0);
  const h3 = num(o[17], 0);
  const h4 = num(o[18], 0);

  const hMax = Math.max(0, h1, 0.8 * h2, 0.6 * h3, 0.4 * h4);
  const prep = clampF((hMax - 0.03) / 0.22, 0, 1);
  const terr = clampF(hMax, 0, 0.45);

  const freq0 = clampF(av(0, BASE_MAIN[0]), 0.5, 4.0);
  const duty0 = clampF(av(1, BASE_MAIN[1]), 0.25, 0.85);
  const phaseOff = wrap1(av(2, BASE_MAIN[2]));
  const stride0 = clampF(av(3, BASE_MAIN[3]), 0.0, 0.7);
  const baseY = clampF(av(4, BASE_MAIN[4]), 0.45, 0.82);
  const lift0 = clampF(av(5, BASE_MAIN[5]), 0.0, 0.5);
  const kneeBias = clampF(av(6, BASE_MAIN[6]), -0.6, 0.6);
  const hipBias = clampF(av(7, BASE_MAIN[7]), -0.5, 0.5);
  const cTorso = clampF(av(8, BASE_MAIN[8]), -2.5, 2.5);
  const phiDes0 = clampF(av(9, BASE_MAIN[9]), -0.9, 0.5);
  const vDes0 = clampF(av(10, BASE_MAIN[10]), -1.0, 3.0);
  const heightTarget = clampF(av(11, BASE_MAIN[11]), 0.60, 1.50);
  const Kh = clampF(av(12, BASE_MAIN[12]), -2.0, 3.0);

  const KxPhi = clampF(av(13, BASE_MAIN[13]), -5.0, 5.0);
  const KxSpin = clampF(av(14, BASE_MAIN[14]), -3.0, 3.0);
  const KxV = clampF(av(15, BASE_MAIN[15]), -4.0, 4.0);
  const KbPhi = clampF(av(16, BASE_MAIN[16]), -400, 400);
  const KbSpin = clampF(av(17, BASE_MAIN[17]), -200, 200);
  const KbV = clampF(av(18, BASE_MAIN[18]), -300, 300);
  const wSwing = clampF(av(19, BASE_MAIN[19]), 0.0, 2.0);

  const kpH = clampF(av(20, BASE_MAIN[20]), 0, 800);
  const kdH = clampF(av(21, BASE_MAIN[21]), 0, 150);
  const kpK = clampF(av(22, BASE_MAIN[22]), 0, 800);
  const kdK = clampF(av(23, BASE_MAIN[23]), 0, 150);
  const kneeStance = clampF(av(24, BASE_MAIN[24]), -1.0, 1.0);
  const contactAdj = Math.max(0, clampF(av(25, BASE_MAIN[25]), 0, 0.2));
  const terrainLiftGain = Math.max(0, clampF(av(26, BASE_MAIN[26]), 0, 2.0));
  const terrainHip = clampF(av(27, BASE_MAIN[27]), -2.0, 2.0);
  const ffHip = clampF(av(28, BASE_MAIN[28]), -1.5, 1.5);
  const ffKnee = clampF(av(29, BASE_MAIN[29]), -1.5, 1.5);
  const rampT = clampF(av(30, BASE_MAIN[30]), 0.02, 1.5);
  const stanceBounce = clampF(av(31, BASE_MAIN[31]), -0.4, 0.4);
  const kneeSwingExtra = clampF(av(32, BASE_MAIN[32]), -1.0, 1.0);

  const stanceAnchor = clampF(ex(0, 0), 0, 1);
  const strideVel = clampF(ex(1, 0), -0.8, 0.8);
  const strideGeom = clampF(ex(2, 0), 0, 1);
  const freqVel = clampF(ex(3, 0), -1.5, 1.5);
  const freqTerrain = clampF(ex(4, 0), -1, 2);
  const dutyVel = clampF(ex(5, 0), -0.4, 0.4);
  const footVelGain = clampF(ex(6, 0), -1, 1);
  const hipPushGain = clampF(ex(7, 0), -200, 200);
  const kneePushGain = clampF(ex(8, 0), -200, 200);
  const pushPhase = clampF(ex(9, 0), 0, 1);
  const heightVyGain = clampF(ex(10, 0), -3, 3);
  const heightSpinGain = clampF(ex(11, 0), -2, 2);
  const groundGain = clampF(ex(12, 0), -0.5, 1.5);
  const swingClearGain = clampF(ex(13, 0), 0, 3);
  const pathClearGain = clampF(ex(14, 0), 0, 3);
  const lookahead = clampF(ex(15, 0), 0, 0.6);
  const hurdleStrideReduce = clampF(ex(16, 0), 0, 1);
  const hurdleLiftGain = clampF(ex(17, 0), 0, 3);
  const hurdleHipGain = clampF(ex(18, 0), -0.4, 0.4);
  const contactPhaseGain = clampF(ex(19, 0), 0, 1);
  const contactLiftGain = clampF(ex(20, 0), 0, 1);
  const heightPitchGain = clampF(ex(21, 0), -2, 2);
  const stanceKneeVel = clampF(ex(22, 0), -1.5, 1.5);
  const bodyHurdleGain = clampF(ex(23, 0), -0.3, 0.5);

  const capGain = clampF(ex(24, 0), -2, 2);
  const vPlaceGain = clampF(ex(25, 0), -2, 2);
  const landingGain = clampF(ex(26, 0), -1.5, 1.5);
  const kneePitchGain = clampF(ex(27, 0), -400, 400);
  const kneeHeightGain = clampF(ex(28, 0), -800, 800);
  const hipHeightGain = clampF(ex(29, 0), -600, 600);
  const exDampH = clampF(ex(30, 0), -60, 120);
  const exDampK = clampF(ex(31, 0), -60, 120);
  const stanceSpring = clampF(ex(32, 0), -0.6, 0.6);
  const speedLean = clampF(ex(33, 0), -0.8, 0.8);
  const contactKnee = clampF(ex(34, 0), -1.5, 1.5);
  const safeHurdle = clampF(ex(35, 0), 0, 1.5);

  let obst = 0;
  if (safeHurdle > 0 && hMax > 0.04) {
    obst = clampF((hMax - 0.04) / 0.20, 0, 1) * safeHurdle;
    if (obst > 1.2) obst = 1.2;
  }

  let M = mem;
  if (!M || typeof M !== "object") M = {};

  if (!M.init || (typeof M.lastT === "number" && t < M.lastT - 0.05)) {
    M.init = 1;
    M.lastT = t;
    M.q = [0, wrap1(phaseOff)];
    M.initH = [hips[0], hips[1]];
    M.initK = [knees[0], knees[1]];
    M.slow = 0;
    M.x = 0;
    M.lastKick = -10;
    M.kickUntil = -1;
    M.prevStance = [0, 0];
    M.anchorX = [0, 0];
  }

  let dt = 1 / 60;
  if (typeof M.lastT === "number") {
    const dd = t - M.lastT;
    if (dd > 0 && dd < 0.2) dt = dd;
  }
  M.lastT = t;

  const rr = clamp01(t / rampT);
  const ramp = rr * rr * (3 - 2 * rr);

  M.x += vx * dt;

  const slowThresh = safeHurdle > 0 ? 0.10 : 0.05;
  if (t > 0.9 && t < 19.5) {
    if (vx < slowThresh && height < 1.05) M.slow += dt;
    else M.slow = Math.max(0, M.slow - dt * 2.5);
  } else {
    M.slow = 0;
  }

  if (M.slow > (safeHurdle > 0 ? 0.70 : 0.90) && t > M.lastKick + 1.0 && t < 18.5) {
    M.kickUntil = t + 0.85;
    M.lastKick = t;
    M.slow = 0;
    M.q[0] = 0;
    M.q[1] = phaseOff;
    M.prevStance = [0, 0];
  }

  const kick = t < M.kickUntil ? 1 : 0;
  const need = clampF(vDes0 - vx, -2.5, 2.5);
  const vErr = vx - vDes0;

  let fUse = freq0 * (1 + clampF(freqVel * need, -0.7, 0.9) + clampF(freqTerrain * prep, -0.5, 1.2));
  if (kick) fUse *= 1.35;
  if (obst > 0) fUse *= (1 - 0.18 * Math.min(1, obst));
  fUse = clampF(fUse, 0.45, 4.8);

  let dutyUse = duty0 + clampF(dutyVel * need, -0.28, 0.28);
  if (obst > 0) dutyUse += 0.10 * Math.min(1, obst);
  dutyUse = clampF(dutyUse, 0.20, 0.90);

  const phaseScale = ramp < 1 ? (0.25 + 0.75 * ramp) : 1;
  M.q[0] = wrap1(M.q[0] + fUse * dt * phaseScale);
  M.q[1] = wrap1(M.q[1] + fUse * dt * phaseScale);

  let em = 0;
  if (t > 0.4) {
    if (height < 0.62) em = Math.max(em, (0.62 - height) / 0.25);
    if (Math.abs(phi) > 0.85 && height < 1.0) em = Math.max(em, (Math.abs(phi) - 0.85) / 0.5);
    if (Math.abs(spin) > 5.0) em = Math.max(em, (Math.abs(spin) - 5.0) / 9.0);
  }
  em = clampF(em, 0, 1);

  const heightErr = heightTarget - height;

  let yBase = baseY + Kh * heightErr;
  yBase += heightVyGain * (-vy);
  yBase += heightSpinGain * spin;
  yBase -= heightPitchGain * Math.abs(phi);
  yBase += bodyHurdleGain * prep;
  if (obst > 0) yBase += 0.025 * Math.min(1, obst);
  if (em > 0) yBase = Math.max(yBase, 0.74 + 0.06 * em);

  let phiDes = phiDes0 + speedLean * clampF(vx, 0, 3);

  const ePhi = phi - phiDes;
  let xBal = KxPhi * ePhi + KxSpin * spin + KxV * vErr;
  xBal += footVelGain * clampF(vErr, -2, 2);
  if (capGain !== 0) xBal += capGain * clampF(vx, -3, 3) * Math.sqrt(Math.max(height, 0.2) / 10.28);
  if (vPlaceGain !== 0) xBal += vPlaceGain * clampF(vErr, -2, 2);

  let balT = KbPhi * ePhi + KbSpin * spin + KbV * vErr;
  if (em > 0) {
    balT *= (1 + 0.55 * em);
    xBal *= (1 - 0.35 * em);
  }

  const geomStride = Math.max(0.015, Math.abs(vx) * dutyUse / (2 * Math.max(fUse, 0.2)));
  let strideUse = stride0 + strideVel * clampF(need, -1.5, 1.5);
  if (strideGeom > 0) strideUse = (1 - strideGeom) * strideUse + strideGeom * geomStride;
  if (hurdleStrideReduce > 0) strideUse *= (1 - hurdleStrideReduce * prep);
  if (obst > 0) strideUse *= (1 - 0.22 * Math.min(1, obst));
  if (kick) strideUse *= 1.30;
  if (em > 0) strideUse *= (1 - 0.70 * em);
  strideUse = clampF(strideUse, 0.01, 0.75);

  const liftUse = lift0 * (1 + 0.6 * kick);

  const out = [0, 0, 0, 0];

  for (let i = 0; i < 2; i++) {
    let q = wrap1(M.q[i]);
    let isStance = q < dutyUse;

    if (t > rampT + 0.12) {
      const denS = 1 - dutyUse;
      if (!isStance && feet[i] > 0.5 && denS > 1e-4) {
        const us = (q - dutyUse) / denS;
        if (us > 0.75 && us < 1.001) {
          q = 0;
          isStance = true;
        }
      } else if (isStance && feet[i] < 0.5 && q > 0.95 * dutyUse) {
        q = dutyUse + 1e-5;
        isStance = false;
      }
    }

    M.q[i] = wrap1(q);

    let u = 0;
    let xPhase = 0;
    let liftAmt = 0;

    if (isStance) {
      u = clampF(q / Math.max(dutyUse, 1e-5), 0, 1);
      xPhase = strideUse * (1 - 2 * u);
    } else {
      const den = Math.max(1 - dutyUse, 1e-4);
      u = clampF((q - dutyUse) / den, 0, 1);
      const sm = u * u * (3 - 2 * u);
      xPhase = strideUse * (-1 + 2 * sm);
      liftAmt = Math.sin(Math.PI * u);
      if (liftAmt < 0) liftAmt = 0;
    }

    const entered = isStance && !M.prevStance[i];
    if (entered) M.anchorX[i] = M.x + xPhase;

    let xVal = xPhase;
    if (isStance && stanceAnchor > 0) {
      let xAnchor = M.anchorX[i] - M.x;
      xAnchor = clampF(xAnchor, -0.8, 0.8);
      xVal = (1 - stanceAnchor) * xPhase + stanceAnchor * xAnchor;
    }

    let xDes = xVal + xBal + terrainHip * terr * liftAmt;
    xDes += hurdleHipGain * prep * (isStance ? 0.3 : 1.0) * liftAmt;
    if (obst > 0) xDes += 0.025 * Math.min(1, obst) * (isStance ? -0.4 : 1.0);
    if (em > 0) xDes *= (1 - 0.4 * em);

    let yDes = yBase;

    if (isStance) {
      yDes += stanceBounce * Math.sin(Math.PI * u);
      if (stanceSpring !== 0) yDes += stanceSpring * Math.sin(Math.PI * u);
      if (feet[i] < 0.5) yDes += contactAdj * (1 + 0.5 * (1 - u));
    } else {
      yDes -= (liftUse + terrainLiftGain * terr) * liftAmt;
      if (feet[i] > 0.5) yDes -= contactAdj * 0.5;
    }

    const xTerr = Math.max(0, xDes);
    const gAt = sampleGround4(xTerr, h1, h2, h3, h4);
    const gPath = maxGround4(xTerr, lookahead, h1, h2, h3, h4);
    const gAtPos = Math.max(0, gAt);
    const gPathPos = Math.max(0, gPath);
    const excess = Math.max(0, gPathPos - gAtPos);

    let gGain = groundGain;
    if (safeHurdle > 0 && gAt > 0) {
      const needG = 0.85 + 0.20 * Math.min(1, obst);
      if (gGain < needG) gGain = needG;
    }
    if (gGain !== 0) yDes -= gGain * gAt;

    if (!isStance) {
      if (swingClearGain > 0) yDes -= swingClearGain * excess * (0.5 + 0.5 * liftAmt);
      if (pathClearGain > 0) yDes -= pathClearGain * gPathPos * liftAmt;
      if (hurdleLiftGain > 0) yDes -= hurdleLiftGain * prep * Math.sqrt(liftAmt);
      if (obst > 0) yDes -= 0.16 * Math.min(1, obst) * Math.sqrt(liftAmt);
      if (landingGain !== 0) yDes -= landingGain * gPathPos * (0.2 + 0.8 * Math.sqrt(liftAmt));
      if (contactLiftGain > 0 && feet[i] > 0.5 && u < 0.85) {
        yDes -= contactLiftGain * (1 - u) * 0.12;
      }
    } else {
      if (hurdleLiftGain > 0) yDes -= hurdleLiftGain * prep * 0.18 * (1 - u);
    }

    if (em > 0) yDes += 0.10 * em;
    yDes = clampF(yDes, 0.15, 0.818);

    const sol = solveIK(xDes, yDes);
    let targetH = hMap * sol[0] - cTorso * phi + hipBias;
    let targetK = kMap * sol[1] + kneeBias;

    if (isStance) {
      targetK += kneeStance * (1 - u);
      if (stanceKneeVel !== 0) targetK += stanceKneeVel * clampF(need, -1.5, 1.5) * (1 - u);
      if (contactKnee !== 0 && feet[i] > 0.5) targetK += contactKnee * (1 - u);
    } else {
      targetK -= kneeSwingExtra * liftAmt;
    }
    if (em > 0) targetK += 0.12 * em;
    if (prep > 0) targetK -= 0.10 * prep * (isStance ? 0.3 : liftAmt);

    targetH = clampF(targetH, -0.89, 1.19);
    targetK = clampF(targetK, -1.68, -0.055);

    if (ramp < 1) {
      const ih = (M.initH && typeof M.initH[i] === "number") ? M.initH[i] : targetH;
      const ik = (M.initK && typeof M.initK[i] === "number") ? M.initK[i] : targetK;
      targetH = ih + (targetH - ih) * ramp;
      targetK = ik + (targetK - ik) * ramp;
    }

    const weight = isStance ? 1.0 : wSwing;
    let hipU = kpH * (targetH - hips[i]) - kdH * hipSpds[i] + balT * weight + ffHip * 210;
    let kneeU = kpK * (targetK - knees[i]) - kdK * kneeSpds[i] + ffKnee * 172 + 35 * em;

    if (hipHeightGain !== 0) hipU += hipHeightGain * heightErr * (isStance ? 1.0 : 0.4);
    if (kneeHeightGain !== 0) kneeU += kneeHeightGain * heightErr * (isStance ? 1.0 : 0.4);
    if (kneePitchGain !== 0) kneeU += kneePitchGain * ePhi * (isStance ? 1.0 : 0.4);
    if (exDampH !== 0) hipU -= exDampH * hipSpds[i];
    if (exDampK !== 0) kneeU -= exDampK * kneeSpds[i];

    const sH = i === 0 ? sHA : sHB;
    const sK = i === 0 ? sKA : sKB;

    if (hipPushGain !== 0 || kneePushGain !== 0) {
      let pushShape = 0;
      if (isStance) {
        const pp = 1 + Math.max(0, pushPhase);
        pushShape = 0.20 + 0.80 * Math.pow(u, pp);
      }
      const pushVal = pushShape * clampF(need, -2.0, 2.0);
      if (hipPushGain !== 0) hipU += sH * hipPushGain * pushVal;
      if (kneePushGain !== 0) kneeU += sK * kneePushGain * pushVal;
    }

    if (!isFinite(hipU)) hipU = 0;
    if (!isFinite(kneeU)) kneeU = 0;

    let ho = sH * hipU / 210;
    let ko = sK * kneeU / 172;

    if (!isFinite(ho)) ho = 0;
    if (!isFinite(ko)) ko = 0;
    if (ho > 1) ho = 1;
    else if (ho < -1) ho = -1;
    if (ko > 1) ko = 1;
    else if (ko < -1) ko = -1;

    out[2 * i] = ho;
    out[2 * i + 1] = ko;
    M.prevStance[i] = isStance ? 1 : 0;
  }

  if (TRACE && TRACE.on) {
    const T = TRACE;
    T.n++;
    const ap = Math.abs(phi);
    const asp = Math.abs(spin);
    T.sumPhi2 += phi * phi;
    T.sumSpin2 += spin * spin;
    T.sumAbsPhi += ap;
    T.sumHeight += height;
    T.sumVx += vx;
    T.sumVx2 += vx * vx;
    if (height < T.minH) T.minH = height;
    if (height > T.maxH) T.maxH = height;
    if (ap > T.maxAbsPhi) T.maxAbsPhi = ap;
    if (asp > T.maxAbsSpin) T.maxAbsSpin = asp;
    if (height < 0.58) T.lowTime += dt;
    if (ap > 1.0) T.badAngleTime += dt;
    if (t > 8) {
      T.tailN++;
      T.tailPhi += phi;
      T.tailVx += vx;
      T.tailHeight += height;
      T.tailAbsPhi += ap;
      T.tailPhi2 += phi * phi;
      T.tailVx2 += vx * vx;
    }
    T.finalT = t;
    T.finalPhi = phi;
    T.finalSpin = spin;
    T.finalVx = vx;
    T.finalVy = vy;
    T.finalHeight = height;
    T.feet = [feet[0], feet[1]];
    T.q = [M.q[0], M.q[1]];
  }

  return out;
}

function learn(lab) {
  const tStart = (typeof Date !== "undefined" && Date.now) ? Date.now() : 0;
  let used = 0;

  const cache = Object.create(null);
  const allRecs = [];
  const elites = [];
  let bestScoreGlobal = -1e100;
  let bestRecGlobal = null;

  function timeOK() {
    if (!tStart) return true;
    return (Date.now() - tStart) < 168000;
  }

  function trialsLeft() {
    try {
      if (lab && typeof lab.trialsLeft === "function") {
        const n = lab.trialsLeft();
        if (typeof n === "number" && isFinite(n)) return n;
      }
    } catch (e) {}
    return 1000 - used;
  }

  function gauss() {
    let u = Math.random();
    if (u < 1e-12) u = 1e-12;
    let v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  function xKey(x) {
    let s = "";
    for (let i = 0; i < x.length; i++) {
      let v = x[i];
      if (typeof v !== "number" || !isFinite(v)) v = 0;
      s += (Math.round(v * 1000000) / 1000000) + ",";
    }
    return s;
  }

  function setMain(x, i, v) {
    x[i] = clampF(v, MIN[i], MAX[i]);
  }

  function setExtra(x, e, v) {
    x[N + 6 + e] = clampF(v, EMIN[e], EMAX[e]);
  }

  function getExtra(x, e) {
    const idx = N + 6 + e;
    let v = x[idx];
    if (typeof v !== "number" || !isFinite(v)) v = 0;
    return clampF(v, EMIN[e], EMAX[e]);
  }

  function safeVariant(base, level) {
    let x = base.slice();
    if (x.length < LEN) {
      const y = BASE_X.slice();
      for (let i = 0; i < x.length; i++) {
        if (typeof x[i] === "number" && isFinite(x[i])) y[i] = x[i];
      }
      x = y;
    }
    setExtra(x, 12, Math.max(getExtra(x, 12), 0.65 + 0.25 * level));
    setExtra(x, 13, Math.max(getExtra(x, 13), 0.65 + 0.25 * level));
    setExtra(x, 14, Math.max(getExtra(x, 14), 0.30 + 0.10 * level));
    setExtra(x, 15, Math.max(getExtra(x, 15), 0.10 + 0.05 * level));
    setExtra(x, 16, Math.max(getExtra(x, 16), 0.25 + 0.10 * level));
    setExtra(x, 17, Math.max(getExtra(x, 17), 0.50 + 0.25 * level));
    setExtra(x, 23, Math.max(getExtra(x, 23), 0.05 + 0.03 * level));
    setExtra(x, 35, Math.max(getExtra(x, 35), level));
    return x;
  }

  function scoreResult(r, tr) {
    if (!r) return -1e12;
    let d = +r.distance;
    if (!isFinite(d)) d = 0;
    let tm = +r.time;
    if (!isFinite(tm)) tm = 0;
    let en = +r.energy;
    if (!isFinite(en)) en = 0;

    if (r.outcome === "invalid" || r.outcome === "error") {
      return -1e10 + d;
    }

    const finished = (r.outcome === "finished" || tm >= 9.95);
    let s = d;
    if (finished) s += 1.2;
    else s -= 2.0 * Math.max(0, 1 - tm / 10);

    if (tr && tr.n > 0) {
      const n = tr.n;
      const rmsPhi = Math.sqrt(tr.sumPhi2 / n);
      const tailN = tr.tailN > 0 ? tr.tailN : 1;
      const tv = tr.tailVx / tailN;

      s += 0.28 * Math.max(0, Math.min(2.0, tv));
      s -= 1.2 * Math.max(0, tr.maxAbsPhi - 1.05);
      s -= 1.8 * Math.max(0, 0.52 - tr.minH);
      s -= 0.8 * Math.max(0, 0.60 - tr.finalHeight);
      s -= 0.7 * Math.max(0, Math.abs(tr.finalPhi) - 0.90);
      s -= 0.15 * Math.max(0, tr.lowTime - 0.9);
      s -= 0.03 * Math.max(0, tr.maxAbsSpin - 12);
      s -= 0.20 * Math.max(0, rmsPhi - 0.85);
      if (tailN > 10) {
        const tailPhi = tr.tailPhi / tailN;
        const tailH = tr.tailHeight / tailN;
        s -= 0.3 * Math.max(0, Math.abs(tailPhi) - 0.8);
        s -= 0.4 * Math.max(0, 0.62 - tailH);
      }
    }

    s -= 0.0000015 * Math.max(0, en);
    return s;
  }

  function evalX(x, force) {
    if (!x || x.length < N) x = BASE_X;
    if (x.length < LEN) {
      const y = BASE_X.slice();
      for (let i = 0; i < Math.min(x.length, LEN); i++) {
        if (typeof x[i] === "number" && isFinite(x[i])) y[i] = x[i];
      }
      x = y;
    }
    const key = xKey(x);
    if (cache[key] !== undefined) return cache[key];
    if (!force && (trialsLeft() <= 0 || !timeOK())) return null;

    TRACE = newTrace();
    let r;
    try {
      r = lab.trial(x);
    } catch (e) {
      r = { distance: 0, outcome: "error", time: 0, energy: 0 };
    }
    const tr = TRACE;
    TRACE = null;
    used++;

    const sc = scoreResult(r, tr);
    const rec = {
      x: x.slice(),
      score: sc,
      r: r,
      tr: tr,
      key: key,
      finished: (r && (r.outcome === "finished" || (+r.time >= 9.90)))
    };

    cache[key] = rec;
    allRecs.push(rec);
    if (sc > bestScoreGlobal) {
      bestScoreGlobal = sc;
      bestRecGlobal = rec;
    }
    return rec;
  }

  function consider(rec) {
    if (!rec) return;
    for (let i = 0; i < elites.length; i++) {
      if (elites[i].key === rec.key) return;
    }
    elites.push(rec);
    elites.sort((a, b) => b.score - a.score);
    if (elites.length > 28) elites.length = 28;
  }

  const seeds = [];
  function addSeed(x) {
    if (!x) return;
    seeds.push(x.slice());
  }

  addSeed(BASE_X);
  addSeed(KNOWN_X);
  addSeed(ATT4_X);
  addSeed(DEF_X);
  addSeed(safeVariant(BASE_X, 0.8));
  addSeed(safeVariant(BASE_X, 1.1));
  addSeed(safeVariant(KNOWN_X, 0.9));
  addSeed(safeVariant(ATT4_X, 0.9));

  for (let j = 0; j < 6; j++) {
    const x = BASE_X.slice();
    x[N + j] *= -1;
    addSeed(x);
  }

  const freqMults = [1.0, 1.06, 1.12, 1.20, 1.30];
  const strideMults = [1.0, 1.10, 1.22, 1.36];
  const vAdds = [0, 0.12, 0.25, 0.40];
  for (let fi = 0; fi < freqMults.length; fi++) {
    for (let si = 0; si < strideMults.length; si++) {
      for (let vi = 0; vi < vAdds.length; vi++) {
        const x = BASE_X.slice();
        setMain(x, 0, x[0] * freqMults[fi]);
        setMain(x, 3, x[3] * strideMults[si]);
        setMain(x, 10, x[10] + vAdds[vi]);
        addSeed(x);
      }
    }
  }

  const dutyVals = [0.30, 0.34, 0.38, 0.42, 0.46, 0.52];
  for (let i = 0; i < dutyVals.length; i++) {
    const x = BASE_X.slice();
    setMain(x, 1, dutyVals[i]);
    addSeed(x);
  }

  const baseYVals = [0.64, 0.68, 0.70, 0.74, 0.78, 0.815];
  for (let i = 0; i < baseYVals.length; i++) {
    const x = BASE_X.slice();
    setMain(x, 4, baseYVals[i]);
    addSeed(x);
  }

  const heightVals = [0.92, 0.98, 1.05, 1.15, 1.25];
  for (let i = 0; i < heightVals.length; i++) {
    const x = BASE_X.slice();
    setMain(x, 11, heightVals[i]);
    addSeed(x);
  }

  const dampVals = [5, 12, 25, 45, 70];
  for (let i = 0; i < dampVals.length; i++) {
    const x = BASE_X.slice();
    setMain(x, 21, dampVals[i]);
    setMain(x, 23, dampVals[i]);
    addSeed(x);
    const y = x.slice();
    setExtra(y, 30, dampVals[i]);
    setExtra(y, 31, dampVals[i]);
    addSeed(y);
  }

  const anchorVals = [0.2, 0.45, 0.7, 0.9];
  for (let i = 0; i < anchorVals.length; i++) {
    const x = BASE_X.slice();
    setExtra(x, 0, anchorVals[i]);
    addSeed(x);
    const y = safeVariant(x, 0.9);
    addSeed(y);
  }

  const geomVals = [0.25, 0.5, 0.75, 1.0];
  for (let i = 0; i < geomVals.length; i++) {
    const x = BASE_X.slice();
    setExtra(x, 2, geomVals[i]);
    addSeed(x);
  }

  const capVals = [-0.6, -0.3, 0.3, 0.6];
  for (let i = 0; i < capVals.length; i++) {
    const x = BASE_X.slice();
    setExtra(x, 24, capVals[i]);
    addSeed(x);
  }

  const pitchVals = [-120, -60, 60, 120];
  for (let i = 0; i < pitchVals.length; i++) {
    const x = BASE_X.slice();
    setExtra(x, 27, pitchVals[i]);
    addSeed(x);
  }

  const heightGainVals = [-300, -150, 150, 300];
  for (let i = 0; i < heightGainVals.length; i++) {
    const x = BASE_X.slice();
    setExtra(x, 28, heightGainVals[i]);
    addSeed(x);
  }

  for (let si = 0; si < seeds.length; si++) {
    if (trialsLeft() <= 10 || !timeOK()) break;
    const rec = evalX(seeds[si]);
    if (rec) consider(rec);
  }

  const DIMS = [];
  for (let i = 0; i < N; i++) DIMS.push(i);
  for (let e = 0; e < E; e++) DIMS.push(N + 6 + e);

  function baseStep(idx) {
    if (idx < N) {
      let w = 1.0;
      if (idx === 21 || idx === 23 || idx === 16 || idx === 17 || idx === 18) w = 0.8;
      return (MAX[idx] - MIN[idx]) * 0.085 * w;
    }
    const e = idx - (N + 6);
    return (EMAX[e] - EMIN[e]) * 0.11;
  }

  function clampDim(idx, v) {
    if (idx < N) return clampF(v, MIN[idx], MAX[idx]);
    const e = idx - (N + 6);
    return clampF(v, EMIN[e], EMAX[e]);
  }

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = (Math.random() * (i + 1)) | 0;
      const t = arr[i];
      arr[i] = arr[j];
      arr[j] = t;
    }
  }

  let current = bestRecGlobal;
  if (!current && elites.length > 0) current = elites[0];

  if (current) {
    let cdScale = 1.0;
    for (let round = 0; round < 3 && trialsLeft() > 45 && timeOK(); round++) {
      let improved = false;
      const order = DIMS.slice();
      shuffle(order);

      for (let oi = 0; oi < order.length; oi++) {
        if (trialsLeft() <= 35 || !timeOK()) break;
        const idx = order[oi];
        const oldVal = current.x[idx];
        const step = baseStep(idx) * cdScale;
        let bestLocal = current;

        for (let d = 0; d < 2; d++) {
          const dir = d === 0 ? 1 : -1;
          const nv = clampDim(idx, oldVal + dir * step);
          if (Math.abs(nv - oldVal) < 1e-10) continue;
          const x = current.x.slice();
          x[idx] = nv;
          const rec = evalX(x);
          if (rec) {
            consider(rec);
            if (rec.score > bestLocal.score + 1e-9) bestLocal = rec;
          }
        }

        if (bestLocal !== current) {
          current = bestLocal;
          improved = true;
        }
      }

      if (!improved) {
        cdScale *= 0.62;
        if (cdScale < 0.14) break;
      }
    }
  }

  let sigma = 0.28;
  let lastBest = bestScoreGlobal;
  let noImp = 0;
  let iter = 0;

  while (trialsLeft() > 24 && timeOK() && iter < 520) {
    iter++;
    if (elites.length === 0) break;

    let parent;
    if (Math.random() < 0.07) {
      parent = { x: BASE_X.slice(), key: "base-random" };
    } else {
      const nUse = Math.min(16, elites.length);
      let idx = Math.floor(Math.pow(Math.random(), 1.55) * nUse);
      if (idx >= nUse) idx = nUse - 1;
      parent = elites[idx];
    }

    let x = parent.x.slice();

    if (Math.random() < 0.22 && elites.length > 1) {
      const nUse = Math.min(12, elites.length);
      const other = elites[(Math.random() * nUse) | 0];
      for (let k = 0; k < DIMS.length; k++) {
        if (Math.random() < 0.35) {
          const idx = DIMS[k];
          x[idx] = other.x[idx];
        }
      }
    }

    let nm;
    const mode = Math.random();
    if (mode < 0.45) nm = 1 + ((Math.random() * 5) | 0);
    else if (mode < 0.82) nm = 4 + ((Math.random() * 13) | 0);
    else nm = 14 + ((Math.random() * 22) | 0);

    for (let c = 0; c < nm; c++) {
      const idx = DIMS[(Math.random() * DIMS.length) | 0];
      const step = baseStep(idx) * sigma * (0.35 + Math.random() * 1.65);
      const dir = Math.random() < 0.5 ? -1 : 1;
      x[idx] = clampDim(idx, x[idx] + dir * step);
    }

    if (Math.random() < 0.025) {
      const j = (Math.random() * 6) | 0;
      x[N + j] *= -1;
    }

    if (Math.random() < 0.10) {
      const r = Math.random();
      if (r < 0.22) setMain(x, 0, MIN[0] + Math.random() * (MAX[0] - MIN[0]));
      else if (r < 0.40) setMain(x, 3, MIN[3] + Math.random() * (MAX[3] - MIN[3]));
      else if (r < 0.56) setMain(x, 10, MIN[10] + Math.random() * (MAX[10] - MIN[10]));
      else if (r < 0.70) setMain(x, 2, Math.random());
      else if (r < 0.84) setMain(x, 1, 0.28 + Math.random() * 0.34);
      else setMain(x, 11, 0.88 + Math.random() * 0.38);
    }

    if (Math.random() < 0.11) {
      const e = (Math.random() * E) | 0;
      setExtra(x, e, MIN[0] + Math.random() * (MAX[0] - MIN[0]));
    }

    const rec = evalX(x);
    if (rec) {
      consider(rec);
      if (rec.score > lastBest + 1e-7) {
        lastBest = rec.score;
        noImp = 0;
        sigma = Math.max(0.075, sigma * 0.95);
      } else {
        noImp++;
        sigma = Math.min(0.62, sigma * 1.004);
        if (noImp > 90) {
          sigma = 0.42;
          noImp = 0;
        }
      }
    }
  }

  if (trialsLeft() > 90 && timeOK() && elites.length > 0) {
    const cdStart = elites[0];
    let cd = cdStart;
    let cdScale = 0.55;
    const order = DIMS.slice();
    shuffle(order);
    for (let oi = 0; oi < order.length; oi++) {
      if (trialsLeft() <= 60 || !timeOK()) break;
      const idx = order[oi];
      const oldVal = cd.x[idx];
      const step = baseStep(idx) * cdScale;
      let bestLocal = cd;
      for (let d = 0; d < 2; d++) {
        const dir = d === 0 ? 1 : -1;
        const nv = clampDim(idx, oldVal + dir * step);
        if (Math.abs(nv - oldVal) < 1e-10) continue;
        const x = cd.x.slice();
        x[idx] = nv;
        const rec = evalX(x);
        if (rec) {
          consider(rec);
          if (rec.score > bestLocal.score + 1e-9) bestLocal = rec;
        }
      }
      if (bestLocal !== cd) cd = bestLocal;
    }
  }

  let sorted = allRecs.slice();
  sorted.sort((a, b) => b.score - a.score);

  const top = [];
  const topKeys = Object.create(null);
  function pushTop(rec) {
    if (!rec || topKeys[rec.key]) return;
    topKeys[rec.key] = 1;
    top.push(rec);
  }

  for (let i = 0; i < sorted.length && top.length < 14; i++) pushTop(sorted[i]);

  const baseCached = cache[xKey(BASE_X)];
  if (baseCached) pushTop(baseCached);

  for (let i = 0; i < top.length; i++) {
    if (trialsLeft() <= 0 || !timeOK()) break;
    const rec = top[i];
    if (!rec) continue;

    if (trialsLeft() > 0 && timeOK()) {
      const sv1 = safeVariant(rec.x, 0.9);
      const r1 = evalX(sv1);
      if (r1) consider(r1);
    }

    if (trialsLeft() > 0 && timeOK()) {
      const sv2 = safeVariant(rec.x, 1.2);
      const r2 = evalX(sv2);
      if (r2) consider(r2);
    }

    if (trialsLeft() > 0 && timeOK()) {
      const x = rec.x.slice();
      setExtra(x, 12, Math.max(getExtra(x, 12), 1.0));
      setExtra(x, 13, Math.max(getExtra(x, 13), 1.0));
      setExtra(x, 14, Math.max(getExtra(x, 14), 0.5));
      setExtra(x, 15, Math.max(getExtra(x, 15), 0.15));
      setExtra(x, 16, Math.max(getExtra(x, 16), 0.38));
      setExtra(x, 17, Math.max(getExtra(x, 17), 0.85));
      setExtra(x, 23, Math.max(getExtra(x, 23), 0.10));
      setExtra(x, 35, Math.max(getExtra(x, 35), 1.2));
      const r3 = evalX(x);
      if (r3) consider(r3);
    }
  }

  if (baseCached && trialsLeft() > 0 && timeOK()) {
    const sb = safeVariant(BASE_X, 1.0);
    const rb = evalX(sb);
    if (rb) consider(rb);
  }

  function finalVal(rec) {
    if (!rec) return -1e100;
    if (!rec.r || rec.r.outcome === "invalid" || rec.r.outcome === "error") return -1e100;
    let s = rec.score;
    const tr = rec.tr;

    if (!rec.finished) s -= 3.0;
    if (tr) {
      s -= 1.5 * Math.max(0, tr.maxAbsPhi - 1.0);
      s -= 3.2 * Math.max(0, 0.55 - tr.minH);
      s -= 1.0 * Math.max(0, 0.62 - tr.finalHeight);
      s -= 0.8 * Math.max(0, Math.abs(tr.finalPhi) - 0.92);
      s -= 0.10 * Math.max(0, tr.maxAbsSpin - 18);
      const tn = tr.tailN > 0 ? tr.tailN : 1;
      s += 0.10 * Math.max(0, Math.min(1.5, tr.tailVx / tn));
    }

    const sv = getExtra(rec.x, 35);
    s += 0.16 * clampF(sv, 0, 1.2);
    const gg = getExtra(rec.x, 12);
    s += 0.04 * clampF(gg - 0.5, 0, 0.6);
    return s;
  }

  let chosen = null;
  let bestFinal = -1e100;
  for (let i = 0; i < allRecs.length; i++) {
    const rec = allRecs[i];
    const fv = finalVal(rec);
    if (fv > bestFinal) {
      bestFinal = fv;
      chosen = rec;
    }
  }

  if (!chosen && baseCached) chosen = baseCached;
  if (!chosen && elites.length > 0) chosen = elites[0];
  if (!chosen && seeds.length > 0) {
    const rec = evalX(seeds[0], true);
    if (rec) chosen = rec;
  }

  TRACE = null;

  if (chosen && chosen.x && chosen.x.length >= LEN) return chosen.x.slice();
  const fallback = BASE_X.slice();
  for (let i = 0; i < LEN; i++) {
    if (typeof fallback[i] !== "number" || !isFinite(fallback[i])) {
      if (i < N) fallback[i] = DEF_MAIN[i];
      else if (i < N + 6) fallback[i] = BASE_SIGNS[i - N];
      else fallback[i] = 0;
    }
  }
  return fallback;
}

