    if (kneeHeightGain !== 0) kneeU += kneeHeightGain * heightErr * (isStance ? 1.0 : 0.4);
    if (kneePitchGain !== 0) kneeU += kneePitchGain * ePhi * (isStance ? 1.0 : 0.4);
    if (exDampH !== 0) hipU -= exDampH * hipSpds[i];
    if (exDampK !== 0) kneeU -= exDampK * kneeSpds[i];

