  const exDampH = clampF(ex(30, 0), -60, 120);
  const exDampK = clampF(ex(31, 0), -60, 120);
  const stanceSpring = clampF(ex(32, 0), -0.6, 0.6);
  const speedLean = clampF(ex(33, 0), -0.8, 0.8);
  const contactKnee = clampF(ex(34, 0), -1.5, 1.5);
