  mem.ph += 2 * Math.PI * fEff * dt;
  const ph = mem.ph;

  const bal = (p.bk !== undefined ? p.bk : 1.303) * lean
            + (p.bd !== undefined ? p.bd : 0.04) * spin
            + (p.bv !== undefined ? p.bv : -0.2035) * (vx - vt);
  const kp = p.kp !== undefined ? p.kp : 3.676;
  const kd = p.kd !== undefined ? p.kd : 0.0;
  const hm = p.hm !== undefined ? p.hm : 0.6797;
  const ha = p.ha !== undefined ? p.ha : 0.2048;
  const km = p.km !== undefined ? p.km : -0.5273;
  const ka = p.ka !== undefined ? p.ka : -0.4675;
  const kph = p.kph !== undefined ? p.kph : -1.1758;
  const pb = p.pb !== undefined ? p.pb : 3.0925;
  // fixed hurdle reflex (not learned)
  const hl = 0.4;
  const hh = 0.15;

  // obstacle height ahead; dead zone so gentle slopes do not trigger the reflex
  const obstacle = Math.max(ahead1, 0.7 * ahead2, 0);
  const liftF = clamp((obstacle - 0.06) / 0.12, 0, 1);

  function leg(phi, hipAng, hipSpd, kneeAng, kneeSpd) {
    const hT = clamp(hm + ha * Math.sin(phi) + bal + hh * liftF, -0.85, 1.15);
    const kT = clamp(km + ka * Math.sin(phi + kph) - hl * liftF, -1.65, -0.1);
    const u1 = clamp(kp * (hT - hipAng) - kd * hipSpd, -1, 1);
    const u2 = clamp(kp * (kT - kneeAng) - kd * kneeSpd, -1, 1);
    return [u1, u2];
  }

  const A = leg(ph, num(o[5]), num(o[6]), num(o[7]), num(o[8]));
  const B = leg(ph + pb, num(o[10]), num(o[11]), num(o[12]), num(o[13]));
  return [A[0], A[1], B[0], B[1]];
}

function learn(lab) {
  const SPEC = [
    { k: 'f',   lo: 0.5,   hi: 3.5,  init: 2.713 },
    { k: 'hm',  lo: -0.6,  hi: 0.8,  init: 0.6797 },
    { k: 'ha',  lo: -0.9,  hi: 0.9,  init: 0.2048 },
    { k: 'km',  lo: -1.5,  hi: -0.1, init: -0.5273 },
    { k: 'ka',  lo: -0.9,  hi: 0.9,  init: -0.4675 },
    { k: 'kph', lo: -3.14, hi: 3.14, init: -1.1758 },
    { k: 'pb',  lo: 0,     hi: 6.283, init: 3.0925 },
    { k: 'kp',  lo: 0.5,   hi: 8,    init: 3.6755 },
    { k: 'kd',  lo: 0,     hi: 1,    init: 0.0 },
    { k: 'bk',  lo: -2,    hi: 2,    init: 1.3031 },
    { k: 'bd',  lo: -0.5,  hi: 0.5,  init: 0.04 },
    { k: 'bv',  lo: -0.6,  hi: 0.6,  init: -0.2035 },
    { k: 'vt',  lo: 1.0,   hi: 4.0,  init: 2.6828 },
    { k: 'gv',  lo: 0,     hi: 1,    init: 0.0 }
  ];
  const hasDate = typeof Date !== 'undefined';
  const t0 = hasDate ? Date.now() : 0;
  const elapsed = () => (hasDate ? Date.now() - t0 : 0);
  const LIMIT_MS = 150000;

  const toP = (x) => {
    const o = {};
    SPEC.forEach((s, i) => {
      const u = Math.min(1, Math.max(0, x[i]));
      o[s.k] = s.lo + u * (s.hi - s.lo);
    });
    return o;
  };
  const toX = (o) => SPEC.map((s) => (o[s.k] - s.lo) / (s.hi - s.lo));
  const gauss = () => {
    let u = 0;
    while (u === 0) u = Math.random();
    const v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };

  const runTrial = (p) => {
    try {
      return lab.trial(p) || null;
    } catch (e) {
      return null;
    }
  };
  const fitOf = (r) => {
    if (!r) return -1000;
    if (r.outcome === 'invalid' || r.outcome === 'error') return -1000;
    return typeof r.distance === 'number' ? r.distance : -1;
  };

  let best = null;
  let bestF = -Infinity;
  let bestX = null;
  let bestNom = -Infinity;

  // Nominal trial; if competitive, also test small frequency perturbations.
  // Fitness blends nominal with the worse perturbed run.
  const ev = (x) => {
    if (lab.trialsLeft() <= 0 || elapsed() > LIMIT_MS) return null;
    const p = toP(x);
    const r = runTrial(p);
    if (!r) return null;
    const nom = fitOf(r);
    let fit = nom;
    if (nom > 0.9 * bestNom && nom > 0 && lab.trialsLeft() >= 2) {
      const pA = Object.assign({}, p, { f: p.f * 0.96 });
      const pB = Object.assign({}, p, { f: p.f * 1.04 });
      const rA = runTrial(pA);
      const rB = runTrial(pB);
      if (rA && rB) {
        const a = fitOf(rA);
        const b = fitOf(rB);
        fit = 0.5 * nom + 0.5 * Math.min(a, b);
      }
    }
    if (nom > bestNom) bestNom = nom;
    if (fit > bestF) {
      bestF = fit;
      best = p;
      bestX = x.slice();
    }
    return fit;
  };

  const seed = SPEC.reduce((o, s) => { o[s.k] = s.init; return o; }, {});
  let m = toX(seed);
  let sigma = 0.015;
  const lam = 10;
  const mu = 3;
  const w = [0.45, 0.3, 0.25];

  if (ev(m) === null) return best || toP(m);
  if (bestX) m = bestX.slice();

  let stall = 0;
  while (lab.trialsLeft() > 0 && elapsed() < LIMIT_MS) {
    const pop = [];
    let stop = false;
    const before = bestF;
    for (let i = 0; i < lam; i++) {
      const x = m.map((v) => v + sigma * gauss());
      const f = ev(x);
      if (f === null) { stop = true; break; }
      pop.push({ x, f });
    }
    if (pop.length === 0) break;
    pop.sort((a, b) => b.f - a.f);
    const k = Math.min(mu, pop.length);
    let wsum = 0;
    for (let i = 0; i < k; i++) wsum += w[i];
    m = m.map((_, j) => {
      let s = 0;
      for (let i = 0; i < k; i++) s += w[i] * pop[i].x[j];
      return Math.min(1.05, Math.max(-0.05, s / wsum));
    });

    if (bestF > before) {
      stall = 0;
      sigma = Math.min(0.03, sigma * 1.05);
    } else {
      stall++;
      sigma = Math.max(0.004, sigma * 0.94);
    }
    if (stall > 30 && bestX) {
      m = bestX.slice();
      sigma = 0.015;
      stall = 0;
    }
    if (stop) break;
  }

  return best || toP(m);
}
